function tmLogo(name){
  /* sorgente principale degli stemmi: cerca il club per nome ed e' quella
     affidabile, quindi viene prima di ogni elenco di numeri */
  try{
    if(typeof window.kfmTeamLogo==='function'){
      var a=window.kfmTeamLogo(name);
      if(a) return a;
    }
  }catch(e){}
  var id=LOGO_TM[name];
  if(!id||/\?/.test(id)) return '';
  return 'https://tmssl.akamaized.net/images/wappen/head/'+id+'.png';
}
function getLogo(id, name) { const ov=name?tmLogo(name):''; if(ov) return ov; if(!id) return `https://ui-avatars.com/api/?name=Team&background=0D1B2A&color=fff`; const t=String(id).replace(/\.0$/,''); if(/^tm/.test(t)) return 'https://tmssl.akamaized.net/images/wappen/head/'+t.slice(2)+'.png'; return `https://images.fifaindex.com/fc26/teams/${t.replace(/^0+/,'')}.webp`; }
function getLeagueLogo(name){
  const id = (typeof LEAGUE_ID!=='undefined' && LEAGUE_ID[name]) ? String(LEAGUE_ID[name]).replace(/\.0$/,'') : '';
  return id ? `https://cdn.sofifa.net/meta/league/${id}/60.png` : '';
}
// stemma di ripiego per una lega = stemma della squadra più forte
function clubCrest(name){ var t=tmLogo(name); if(t) return t;
  try{ if(typeof EADB!=='undefined'&&EADB[name]) return getLogo(EADB[name].tid,name); }catch(e){}
  return ''; }
function leagueFallbackLogo(name){ const cl=(typeof LEAGUES!=='undefined'&&LEAGUES[name])?LEAGUES[name][0]:null; return cl&&EADB[cl]?getLogo(EADB[cl].tid, cl):'https://ui-avatars.com/api/?name=L'; }
// loghi competizioni: Champions/Europa/Conference + campionati nazionali
const EURO_LOGO={CL:'https://media.api-sports.io/football/leagues/2.png',EL:'https://media.api-sports.io/football/leagues/3.png',CO:'https://media.api-sports.io/football/leagues/848.png'};
function compLogoUrl(t){ if(!t) return ''; if(String(t).indexOf('CL')===0){ const id=EURO_LOGO[S.euroComp]||'2'; return `https://cdn.sofifa.net/meta/league/${id}/60.png`; } return getLeagueLogo(S.leagueName)||leagueFallbackLogo(S.leagueName); }
function compLogoFallback(t){ if(String(t).indexOf('CL')===0){ const ab=S.euroComp==='EL'?'EL':S.euroComp==='CO'?'CO':'CL'; return 'https://ui-avatars.com/api/?name='+ab+'&background=3D6FE0&color=fff&bold=true'; } return leagueFallbackLogo(S.leagueName)||'https://ui-avatars.com/api/?name=SA&background=00A85A&color=fff&bold=true'; }
function getFace(id, name) {
  if(String(id).charAt(0)==='R') return 'https://i.pravatar.cc/150?u=rg'+id;
  if(!id || id === '0') return `https://ui-avatars.com/api/?name=${(name||'P').replace(/ /g, '+')}&background=E2EBF4&color=0D1B2A`;
  const n = String(id).replace(/\.0$/,'').replace(/^0+/,'');
  return `https://cmtracker.fra1.cdn.digitaloceanspaces.com/DB/26/heads/p${n}.png`;
}
