function wTie(a,b){ const sa=wClub(a).str, sb=wClub(b).str; const r1=wSimMatch(sa,sb), r2=wSimMatch(sb,sa); const g1=r1.gfA+r2.gfB, g2=r1.gfB+r2.gfA; return g1>g2?a:(g2>g1?b:(Math.random()>0.5?a:b)); }
