function wEuroMatchday(comp){ const E=S.world.euro[comp]; if(!E||E.isUser||E.mdPlayed>=8) return; let teams=shuffle(Object.keys(E.standings)); for(let i=0;i+1<teams.length;i+=2){ const a=teams[i], b=teams[i+1]; const r=wSimMatch(wClub(a).str, wClub(b).str); wUpdate(E.standings[a], r.gfA, r.gfB); wUpdate(E.standings[b], r.gfB, r.gfA); wScore('eu:'+comp,a,r.gfA); wScore('eu:'+comp,b,r.gfB); } E.mdPlayed++; }
