function wPlayCupRound(lg){ const C=S.world.cups[lg]; if(!C||C.champion) return; if(C.alive.length<2){ if(C.alive.length===1) C.champion=C.alive[0]; return; } if(C.alive.length===2){ const w=wTie(C.alive[0],C.alive[1]); const l=(C.alive[0]===w?C.alive[1]:C.alive[0]); wScore('cup:'+lg,w,1+rnd(2)); wScore('cup:'+lg,l,rnd(2)); C.runnerUp=l; C.champion=w; C.alive=[w]; return; } let t=shuffle(C.alive.slice()); let winners=[]; if(t.length%2) winners.push(t.pop()); for(let i=0;i<t.length;i+=2){ const w=wTie(t[i],t[i+1]); const l=(t[i]===w?t[i+1]:t[i]); wScore('cup:'+lg,w,1+rnd(2)); wScore('cup:'+lg,l,rnd(2)); winners.push(w); } C.alive=winners; }
function wPlaySupercup(lg){ const cup=S.world.cups[lg]; let lc=null; if(lg===S.leagueName){ const r=Object.entries(S.saStandings).sort((x,y)=>y[1].pts-x[1].pts||y[1].gd-x[1].gd); lc=r.length?r[0][0]:null; } else { const L=S.world.leagues[lg]; const r=L?Object.entries(L.standings).sort((x,y)=>y[1].pts-x[1].pts||y[1].gd-x[1].gd):[]; lc=r.length?r[0][0]:null; } const cc=cup?cup.champion:null; if(!lc||!cc){ S.world.supers[lg]={champion:lc||cc, a:lc, b:cc}; return; } if(lc===cc){ S.world.supers[lg]={champion:lc, a:lc, b:cc}; return; } const w=wTie(lc,cc); S.world.supers[lg]={champion:w, a:lc, b:cc}; }
