function ncBuild(){ const lg=S.leagueName; let pool=((typeof LEAGUES!=='undefined'&&LEAGUES[lg])?LEAGUES[lg].slice():[]).filter(c=>c!==S.teamName && typeof EADB!=='undefined' && EADB[c]); pool=shuffle(pool); const roundNames=['Sedicesimi','Ottavi','Quarti','Semifinale','Finale']; S.nationalCup={ league:lg, cupName:(CUP_NAMES[lg]||'Coppa Nazionale'), pool, used:[], round:0, roundsTot:5, roundNames, roundName:roundNames[0], userOut:false, userOpp:null, eliminatedBy:null, champion:null, runnerUp:null }; }
function ncPickOpponent(){ const NC=S.nationalCup; let cand=NC.pool.filter(c=>!NC.used.includes(c)); if(!cand.length) cand=NC.pool.slice(); cand.sort((a,b)=>((EADB[b]?EADB[b].str:70)-(EADB[a]?EADB[a].str:70))); const slice=cand.slice(0, Math.max(3, cand.length-NC.round*3)); const opp=slice[rnd(slice.length)]||cand[0]; NC.used.push(opp); NC.roundName=NC.roundNames[Math.min(NC.round, NC.roundNames.length-1)]; return opp; }
function ncResolveUserRound(opp, win){ const NC=S.nationalCup; if(win){ NC.round++; NC.roundName=NC.roundNames[Math.min(NC.round, NC.roundNames.length-1)]; if(NC.round>=NC.roundsTot){ NC.champion=S.teamName; NC.runnerUp=opp; } ncSyncWorld(); } else { NC.userOut=true; NC.eliminatedBy=opp; ncFinishWithoutUser(opp); } }
function ncFinishWithoutUser(lastOpp){ const NC=S.nationalCup; let contenders=NC.pool.filter(c=>typeof EADB!=='undefined'&&EADB[c]); contenders.sort((a,b)=>((EADB[b]?EADB[b].str:70)-(EADB[a]?EADB[a].str:70))); let alive=contenders.slice(0,8); if(lastOpp&&!alive.includes(lastOpp)) alive.unshift(lastOpp); while(alive.length>1){ let nx=[]; for(let i=0;i<alive.length;i+=2){ if(i+1>=alive.length){ nx.push(alive[i]); continue; } nx.push(wTie(alive[i],alive[i+1])); } alive=nx; } NC.champion=alive[0]||lastOpp; NC.runnerUp=lastOpp; ncSyncWorld(); }
function ncSyncWorld(){ if(!S.world) return; const lg=S.leagueName; const NC=S.nationalCup; if(!NC) return; if(!S.world.cups[lg]) S.world.cups[lg]={alive:[],champion:null,runnerUp:null}; if(NC.champion){ S.world.cups[lg].champion=NC.champion; S.world.cups[lg].runnerUp=NC.runnerUp; S.world.cups[lg].alive=[NC.champion]; } else { const left=NC.userOut?[]:[S.teamName]; const others=NC.pool.filter(c=>!NC.used.includes(c)).slice(0, Math.max(1, 8-NC.round)); S.world.cups[lg].alive=left.concat(others); } }

