function renderCupView(lg){ const C=S.world?S.world.cups[lg]:null; const sup=S.world?S.world.supers[lg]:null; const name=CUP_NAMES[lg]||'Coppa'; const co=(typeof LEAGUE_COUNTRY!=='undefined'&&LEAGUE_COUNTRY[lg])||''; const crest=((typeof CUP_LOGO_API!=='undefined'&&CUP_LOGO_API[lg])?apiCompLogo(CUP_LOGO_API[lg]):(getLeagueLogo(lg)||leagueFallbackLogo(lg))); let html=`<div class='cup-head'><img class='cup-crest' src='${crest}' onerror="this.src='${leagueFallbackLogo(lg)}'"><div><div class='cup-name'>${name}</div><div class='cup-co'>${co}</div></div></div>`; if(C&&C.champion){ html+=`<div class='comp-champ'>🏆 Vincitore: <b>${C.champion}</b>${C.runnerUp?` <span style='opacity:.6'>· finalista ${C.runnerUp}</span>`:''}</div>`; } else if(C){ html+=`<div class='comp-champ pending'>In corso · ${C.alive.length} squadre ancora in gara</div><div class='cup-alive'>${C.alive.map(t=>`<span class='cup-pill' data-team="${t}">${t}</span>`).join('')}</div>`; } else { html+=`<div class='comp-champ pending'>Coppa non ancora disponibile</div>`; } const sn=SUPERCUP_NAMES[lg]||'Supercoppa'; if(sup&&sup.champion){ html+=`<div class='comp-champ' style='margin-top:10px'>🏅 ${sn}: <b>${sup.champion}</b>${(sup.a&&sup.b)?` <span style='opacity:.6'>(${sup.a} vs ${sup.b})</span>`:''}</div>`; } else { html+=`<div class='comp-champ pending' style='margin-top:10px'>${sn}: a fine stagione</div>`; } return html; }
