// Coordinate Modulo
const FORMATION_SLOTS = [
  { id: 0, role: "POR", x: 50, y: 86 }, { id: 1, role: "TS", x: 18, y: 66 }, { id: 2, role: "DC", x: 38, y: 72 },
  { id: 3, role: "DC", x: 62, y: 72 }, { id: 4, role: "TD", x: 82, y: 66 }, { id: 5, role: "CC", x: 30, y: 46 },
  { id: 6, role: "CDC", x: 50, y: 56 }, { id: 7, role: "CC", x: 70, y: 46 }, { id: 8, role: "AS", x: 22, y: 24 },
  { id: 9, role: "ATT", x: 50, y: 15 }, { id: 10, role: "AD", x: 78, y: 24 }
];

const rnd=n=>Math.floor(Math.random()*n);

/* ---- ruoli & miglior formazione ---- */
const ROLEMAP = { "POR":["POR"], "DC":["DC"], "TD":["TD","ED","DC"], "TS":["TS","ES","DC"], "CDC":["CDC","CC","DC"], "CC":["CC","CDC","COC"], "AD":["AD","ED","ATT"], "AS":["AS","ES","ATT"], "ATT":["ATT","AT","AS","AD","COC"] };
const ROLE_IT = { POR:"Portiere", DC:"Difensore centrale", TD:"Terzino destro", TS:"Terzino sinistro", ED:"Esterno destro", ES:"Esterno sinistro", CDC:"Mediano", CC:"Centrocampista", COC:"Trequartista", AD:"Ala destra", AS:"Ala sinistra", AT:"Seconda punta", ATT:"Attaccante" };
function compatRole(player, slotRole){ return player.roles.some(r => ROLEMAP[slotRole].includes(r)); }
// sceglie la migliore XI da un roster: assegna a ogni slot il miglior compatibile non usato
function isGKp(p){ return !!(p&&p.roles&&p.roles.indexOf('POR')>=0); }
/* quanto perde un giocatore fuori dal suo ruolo (0 = ruolo naturale) */
function posPenaltyC(p, slotRole){
  if(!p) return 99;
  if(isGKp(p)!==(slotRole==='POR')) return 99;      /* portiere e movimento non si mescolano */
  if(slotRole==='POR') return 0;
  if(!p.roles||!p.roles.length) return 14;
  if(p.roles[0]===slotRole) return 0;
  if(compatRole(p,slotRole)) return 2;
  const LINE={POR:'D',DC:'D',TD:'D',TS:'D',ED:'D',ES:'D',CDC:'C',CC:'C',COC:'C',AD:'A',AS:'A',AT:'A',ATT:'A'};
  return (LINE[p.roles[0]]===LINE[slotRole])?6:14;
}
function rateIn(p, slotRole){
  if(!p||!slotRole) return 1;
  const pen=posPenaltyC(p,slotRole);
  return Math.max(1, (p?p.rate:0) - (pen>=99?30:pen));
}
function pickBestXI(roster){
  const used=new Set(); const xi=new Array(11).fill(null);
  const order=[0,2,3,1,4,6,5,7,9,8,10]; // priorità: spina dorsale prima
  order.forEach(si=>{
    const role=FORMATION_SLOTS[si]&&FORMATION_SLOTS[si].role;
    if(!role) return;
    let best=null,bi=-1,bs=-1;
    roster.forEach((p,idx)=>{
      if(used.has(idx)||!p) return;
      if(posPenaltyC(p,role)>=99) return;            /* niente attaccanti in porta */
      const sc=p.rate-posPenaltyC(p,role)*3;
      if(sc>bs){ bs=sc; best=p; bi=idx; }
    });
    if(bi<0){ roster.forEach((p,idx)=>{
      if(used.has(idx)||!p) return;
      if(role!=='POR'&&isGKp(p)) return;             /* il portiere non fa il terzino */
      if(!best||p.rate>best.rate){ best=p; bi=idx; }
    }); }
    if(bi>=0){ xi[si]=roster[bi]; used.add(bi); }
  });
  const bench = roster.filter((p,idx)=>!used.has(idx)&&p).sort((a,b)=>b.rate-a.rate);
  return { xi, bench };
}
function squadValueOf(list){ return Math.round(list.filter(Boolean).reduce((a,p)=>a+playerPrice(p),0)); }
function recalcStrength(){ const v=[]; (S&&S.draft&&S.draft.xi?S.draft.xi:[]).forEach((p,i)=>{ if(p&&FORMATION_SLOTS[i]) v.push(rateIn(p,FORMATION_SLOTS[i].role)); });
  S.strength = v.length? Math.round(v.reduce((a,b)=>a+b,0)/v.length) : 0; }
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=rnd(i+1);[a[i],a[j]]=[a[j],a[i]]}return a};
function poisson(l){let L=Math.exp(-l),k=0,p=1;do{k++;p*=Math.random()}while(p>L);return Math.min(5, k-1);}

