function loadMusic() {
  fetch('music/manifest.json').then(r=>r.json()).then(list=>{
    MUSIC.tracks = Array.isArray(list) ? list : (list.tracks||[]);
    MUSIC.ready = true; MUSIC.i = rnd(MUSIC.tracks.length||1);
  }).catch(()=>{ MUSIC.tracks = MUSIC_FALLBACK; MUSIC.ready = true; });
}
loadMusic();

function getYear() { return S.baseYear + S.season - 1; }

const MAX_SEASONS = 30;
function leagueTier(lg){ lg=String(lg||''); if(lg.indexOf('Serie C')===0||lg==='Serie D') return 'c'; if(lg==='Serie B'||lg==='La Liga 2'||lg==='Ligue 2') return 'b'; return 'a'; }
function seasonPrize(){
  const rnk = Object.entries(S.saStandings).sort((x,y)=>y[1].pts-x[1].pts || (y[1].gd||0)-(x[1].gd||0) || y[1].gf-x[1].gf);
  const pos = rnk.map(e=>e[0]).indexOf(S.teamName)+1;
  const lines=[]; let prize=0;
  const _lt=leagueTier(S.leagueName);
  const _LTAB={a:(p)=>p===1?80:p===2?55:p===3?42:p===4?34:p<=6?24:p<=10?16:p<=15?11:8, b:(p)=>p===1?22:p===2?15:p===3?11:p<=8?6:p<=15?3:1.5, c:(p)=>p===1?3.2:p===2?2:p<=5?1.3:p<=10?0.7:p<=15?0.45:0.25};
  const lp = Math.round(((_LTAB[_lt]||_LTAB.a)(pos||20))*100)/100;
  prize+=lp; lines.push({k:`${S.leagueName||'Campionato'} (${pos||'-'}° posto)`, v:lp});
  if(S.euroComp && S.clStandings && S.clStandings[S.teamName]){
    const cl=Object.entries(S.clStandings).sort((x,y)=>y[1].pts-x[1].pts || (y[1].gd||0)-(x[1].gd||0) || y[1].gf-x[1].gf);
    const cpos=cl.map(e=>e[0]).indexOf(S.teamName)+1;
    const PB={CL:{base:14,top:10,mid:5,r16:8,qf:12,sf:18,fin:25,win:35},EL:{base:8,top:6,mid:3,r16:5,qf:7,sf:10,fin:14,win:20},CO:{base:5,top:4,mid:2,r16:3,qf:5,sf:7,fin:9,win:13}};
    const pb=PB[S.euroComp]||PB.CL;
    const ev=t=>S.history.some(h=>h.type===t && h.res && h.res!=='-');
    let cp=pb.base; if(cpos&&cpos<=8)cp+=pb.top; else if(cpos&&cpos<=24)cp+=pb.mid;
    let stage='Fase Lega';
    if(ev('CL_R16_1')||ev('CL_R16_2')){ cp+=pb.r16; stage='Ottavi'; }
    if(ev('CL_QF1')||ev('CL_QF2')){ cp+=pb.qf; stage='Quarti'; }
    if(ev('CL_SF1')||ev('CL_SF2')){ cp+=pb.sf; stage='Semifinale'; }
    if(ev('CL_F')){ cp+=pb.fin; stage='Finalista'; if(S.history.some(h=>h.type==='CL_F'&&h.res==='W')){ cp+=pb.win; stage='VINCITORE'; } }
    prize+=cp; lines.push({k:`${euroCompName(S.euroComp)} (${cpos||'-'}° · ${stage})`, v:cp});
  }
  if(S.nationalCup){
    const NC=S.nationalCup; const cupName=CUP_NAMES[S.leagueName]||'Coppa Nazionale';
    const _nt=leagueTier(S.leagueName);
    const _NCT={a:{tab:[0.3,0.4,0.8,1.5,1.9],win:5.5}, b:{tab:[0.12,0.2,0.4,0.7,1.1],win:1.8}, c:{tab:[0.005,0.01,0.05,0.15,0.3],win:0.6}};
    const _ncc=_NCT[_nt]||_NCT.a; const rr=Math.max(0,Math.min(NC.round||0,4)); let np=_ncc.tab[rr];
    let st = NC.champion===S.teamName ? 'Vincitore' : NC.userOut ? ('Eliminato'+(NC.roundName?' · '+NC.roundName:'')) : (NC.roundName||'In corso');
    if(NC.champion===S.teamName) np=_ncc.win;
    np=Math.round(np*100)/100;
    prize+=np; lines.push({k:`${cupName} (${st})`, v:np});
  }
  if(SUPERCUP_NAMES[S.leagueName] && S.history && S.history.some(h=>h.type==='SUP')){
    const sn=SUPERCUP_NAMES[S.leagueName]; const won=!!S._supWon;
    const _st=leagueTier(S.leagueName); const _SUP={a:[12,5],b:[4,2],c:[0.8,0.3]}; const _sv=(_SUP[_st]||_SUP.a); const spv=won?_sv[0]:_sv[1];
    prize+=spv; lines.push({k:`${sn} (${won?'Vincitore':'Finalista'})`, v:spv});
  }
  return { prize:Math.round(prize*100)/100, pos, lines };
}
function seasonDevelopment(){
  const dev=(p)=>{ if(!p) return; const st=S.playerStats[p.name]; if(!st) return;
    const perf=(st.goals||0)+(st.clGoals||0)+((st.assists||0)+(st.clAssists||0))*0.7;
    let potUp=0, rateUp=0;
    if(perf>=20){ potUp=3; rateUp=2; } else if(perf>=12){ potUp=2; rateUp=1; } else if(perf>=6){ potUp=1; rateUp=1; }
    if(potUp){ p.pot=Math.min(99,(p.pot||p.rate)+potUp); }
    if(rateUp && p.rate<(p.pot||p.rate)){ p.rate=Math.min(p.pot,p.rate+rateUp);
      ['pac','sho','pas','dri','def','phy'].forEach(k=>{ p[k]=Math.min(99,(parseInt(p[k])||p.rate)+rateUp); }); }
  };
  S.draft.xi.forEach(dev); S.bench.forEach(dev);
}
function growPlayer(p){
  if(!p) return;
  p.age = parseInt(p.age) + 1;
  const pot = p.pot || p.rate;
  if(p.age <= 23 && p.rate < pot){
    const up = Math.min(pot - p.rate, 1 + rnd(3));
    p.rate += up;
    ['pac','sho','pas','dri','def','phy'].forEach(k=>{ p[k] = Math.min(99, (parseInt(p[k])||p.rate) + up); });
  } else if(p.age >= 31){
    p.rate = Math.max(60, p.rate - (Math.random()<0.5?1:0));
  }
}
function increaseAges() {
    S.draft.xi.forEach(growPlayer);
    S.bench.forEach(growPlayer);
    [DB_SERIE_A, ROSTERS_CL].forEach(db => { Object.values(db).forEach(team => { team.r.forEach(growPlayer); }); });
}

