function simulateWorldTransfers(){
  if(typeof EADB==='undefined') return;
  if(!S.freeAgents) S.freeAgents=[];
  const clubs=Object.keys(EADB).filter(cn=>cn!==S.teamName && EADB[cn] && EADB[cn].r);
  const rOf=l=>parseInt(String(l).split('|')[2])||60;
  const aOf=l=>parseInt(String(l).split('|')[5]||'25')||25;
  clubs.forEach(cn=>{
    const club=EADB[cn]; const str=club.str||70;
    let deals=4+rnd(6);
    while(deals-->0){
      if(club.r.length>22 && Math.random()<0.55){
        let wi=-1, wr=999;
        club.r.forEach((l,i)=>{ const rr=rOf(l); if((aOf(l)>=31 || rr<str-8) && rr<wr){ wr=rr; wi=i; } });
        if(wi>=0){ if(Math.random()<0.75) S.freeAgents.push(club.r[wi]); club.r.splice(wi,1); }
      }
      const want=str-1+rnd(6);
      let pool=[];
      if(S.freeAgents.length){ S.freeAgents.forEach((l,i)=>{ if(S.faProtected && S.faProtected[String(l).split('|')[0]]>0) return; const rr=rOf(l); if(rr>=want-3 && rr<=want+4) pool.push(['fa',i,rr]); }); }
      const seller=clubs[rnd(clubs.length)];
      if(seller && seller!==cn && EADB[seller] && EADB[seller].r && EADB[seller].r.length>20 && (EADB[seller].str||70)<=str+1){
        EADB[seller].r.forEach((l,i)=>{ const rr=rOf(l); if(rr>=want-2 && rr<=want+3 && rr<87) pool.push([seller,i,rr]); });
      }
      if(!pool.length) continue;
      pool.sort((x,y)=>y[2]-x[2]);
      const pick=pool[rnd(Math.min(4,pool.length))];
      if(pick[0]==='fa'){ club.r.push(S.freeAgents[pick[1]]); S.freeAgents.splice(pick[1],1); }
      else { const sc=EADB[pick[0]]; if(sc&&sc.r&&sc.r[pick[1]]){ club.r.push(sc.r[pick[1]]); sc.r.splice(pick[1],1); } }
    }
    const rates=club.r.map(rOf).sort((a,b)=>b-a).slice(0,11);
    if(rates.length) club.str=Math.round(rates.reduce((a,b)=>a+b,0)/rates.length);
  });
  if(S.faProtected){ for(var _fk in S.faProtected){ S.faProtected[_fk]=(S.faProtected[_fk]||0)-1; if(S.faProtected[_fk]<=0) delete S.faProtected[_fk]; } }
  if(S.freeAgents.length>400) S.freeAgents=S.freeAgents.sort((a,b)=>rOf(b)-rOf(a)).slice(0,400);
}
function buildCarrieraSchedule() {
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  try{ if(typeof MU_repairSave==='function' && S && S.freeAgents && S.freeAgents.length) MU_repairSave(); }catch(e){}
  try{ if((!S.freeAgents||S.freeAgents.length<30) && typeof generateFreeAgents==='function') generateFreeAgents(); }catch(e){}
  try{ topUpFreeAgents(); }catch(e){}

  const saOpps = Object.keys(DB_SERIE_A);
  let clPool = shuffle(euroListFor(S.euroComp)).filter(t => t !== S.teamName);
  const clOpps = clPool.slice(0, 35); 
  
  let andata = shuffle(saOpps);
  let ritorno = shuffle(saOpps);
  
  // Data d'inizio: prima domenica dopo il 22 agosto dell'anno sportivo
  let startYear = getYear();   /* la prima stagione e' 2026/27, non 2025/26 */
  let start = new Date(startYear, 7, 22);
  while (start.getDay() !== 0) start.setDate(start.getDate() + 1);
  const addDays = (base, n) => { let d = new Date(base); d.setDate(d.getDate() + n); return d; };
  if(S.supercupNext && S.supercupNext.opp){ const so=S.supercupNext.opp; let sd=(typeof euroClubData==='function'?euroClubData(so):null); if(!sd){ sd=(typeof EADB!=='undefined'&&EADB[so])?{logo:EADB[so].tid,str:EADB[so].str}:{logo:0,str:80}; } S.calendar.push({ week:0, type:'SUP', name:so, logo:getLogo(sd.logo), str:sd.str||80, home:true, played:false, date: addDays(start,-3).getTime() }); }

  let clMatchIndex = 0;
  const nOpp = saOpps.length;            // avversari di lega (tu sei la squadra N+1)
  const totWeeks = nOpp * 2;             // andata + ritorno
  const clEvery = Math.max(3, Math.floor(totWeeks/8)); // ~8 gare CL distribuite
  ncBuild();
  const ncWeeks=[Math.max(2,Math.round(totWeeks*0.15)),Math.round(totWeeks*0.3),Math.round(totWeeks*0.45),Math.round(totWeeks*0.62),Math.round(totWeeks*0.8)];
  const ncWeeksSet=new Set(ncWeeks);
  for(let w=1; w<=totWeeks; w++) {
      let opp = (w <= nOpp) ? andata[w-1] : ritorno[w-1-nOpp];
      let saDate = addDays(start, (w-1)*7 - (w % 3 === 0 ? 1 : 0));
      S.calendar.push({ week: w, type: "SA", name: opp, logo: getLogo(DB_SERIE_A[opp].logo), str: DB_SERIE_A[opp].str, home: w%2===0, played: false, date: saDate.getTime() });

      if(ncWeeksSet.has(w)){ let ncDate=addDays(start,(w-1)*7+2); S.calendar.push({ week:w, type:'NC', name:'—', logo:getLogo(null), str:78, home:true, played:false, date:ncDate.getTime() }); }
  }
  if(S.euroComp){
    const _spring=startYear+1;
    const _md=(mo,d)=> new Date(startYear, mo, d);
    const _sd=(mo,d)=> new Date(_spring, mo, d);
    const _off=S.euroComp==='CL'?0:2;
    const _clL=[_md(8,17),_md(9,1),_md(9,22),_md(10,5),_md(10,26),_md(11,9),_sd(0,21),_sd(0,28)];
    for(let i=0;i<8;i++){ const clOpp=clOpps[i]; if(!clOpp) continue; const clData=euroClubData(clOpp)||{logo:0,str:78}; S.calendar.push({ week:'CL', type:'CL_L', name:clOpp, logo:getLogo(clData.logo), str:clData.str, home:i%2===0, played:false, date:addDays(_clL[i],_off).getTime() }); }
    const _ko=[['CL_PO1',_sd(1,11)],['CL_PO2',_sd(1,18)],['CL_R16_1',_sd(2,4)],['CL_R16_2',_sd(2,11)],['CL_QF1',_sd(3,8)],['CL_QF2',_sd(3,15)],['CL_SF1',_sd(3,29)],['CL_SF2',_sd(4,6)],['CL_F',_sd(4,31)]];
    _ko.forEach(function(x){ S.calendar.push({ week:'KO', type:x[0], name:'Da definire', logo:getLogo(null), str:80, home:true, played:false, date:addDays(x[1],_off).getTime() }); });
    S._koBaseDate=addDays(_sd(4,31),_off).getTime();
  } else {
    S._koBaseDate=addDays(start, totWeeks*7).getTime();
  }
  S.calendar.push({ week:'BDO', type:'BDO', name:"Pallone d'Oro", logo:getLogo(null), str:0, home:true, played:false, date:new Date(startYear,9,26).getTime() });
  S.calendar.sort(function(a,b){ return a.date-b.date; });
  
  S.saStandings[S.teamName] = initTeam(true, S.userLogo);
  saOpps.forEach(o => S.saStandings[o] = initTeam(false, getLogo(DB_SERIE_A[o].logo)));
  
  if(S.euroComp){
    S.clStandings[S.teamName] = initTeam(true, S.userLogo);
    clOpps.forEach(o => { 
        let cd = euroClubData(o);
        S.clStandings[o] = initTeam(false, getLogo(cd?cd.logo:0)); 
    });
  }
  S.currentDay = S.calendar[0] ? S.calendar[0].date - 4*86400000 : start.getTime();
  S.selCalDay = null;
  initWorld(S.calendar[0] ? S.calendar[0].date - 7*86400000 : start.getTime(), (S._koBaseDate||start.getTime()) + 70*86400000);
  simulateWorldUpTo(S.currentDay);
  ncSyncWorld();
}

function initTeam(isYou, logo) { return {p:0, w:0, d:0, l:0, gf:0, ga:0, gd:0, pts:0, you:isYou, logo, cs:0}; }
function updateRow(t, res, gf, ga) { t.p++; t.gf+=gf; t.ga+=ga; t.gd = t.gf - t.ga; if(res==="W"){t.pts+=3; t.w++;} else if(res==="D"){t.pts+=1; t.d++;} else{t.l++;} if(ga===0) t.cs++; }

