function processStats(name, team, type, isCL, img) {
  if(!S.playerStats[name]) S.playerStats[name] = { team, goals:0, assists:0, clGoals:0, clAssists:0, cupGoals:0, cupAssists:0, img };
  if(S.playerStats[name].cupGoals==null){ S.playerStats[name].cupGoals=0; S.playerStats[name].cupAssists=0; }
  if(S._curMatchType==='NC'){
      if(type==='goals') S.playerStats[name].cupGoals++; else S.playerStats[name].cupAssists++;
  } else if(isCL) {
      if(type==='goals') S.playerStats[name].clGoals++;
      if(type==='assists') S.playerStats[name].clAssists++;
  } else {
      S.playerStats[name][type]++;
  }
  if(S._curMatchType!=='SUP'){
    let _ck = S._curMatchType==='NC' ? ('cup:'+(S.leagueName||'Serie A')) : isCL ? ('eu:'+(S.euroComp||'CL')) : ('lg:'+(S.leagueName||'Serie A'));
    addCompStat(_ck, name, team, type, img);
  }
}
function addCompStat(key,name,team,type,img){
  if(!key||!name) return;
  if(!S.compStats) S.compStats={};
  if(!S.compStats[key]) S.compStats[key]={};
  const m=S.compStats[key];
  if(!m[name]) m[name]={team:team||'',g:0,a:0,img:img||AVP};
  if(type==='goals') m[name].g++; else m[name].a++;
  if(team) m[name].team=team;
  if(img) m[name].img=img;
}
function _wPick(pool){ if(!pool||!pool.length) return null; var tot=0,ws=[]; for(var i=0;i<pool.length;i++){ var r=(pool[i].rate||70); var w=Math.pow(Math.max(1,r-58),2.4); ws.push(w); tot+=w; } if(tot<=0) return pool[rnd(pool.length)]; var x=Math.random()*tot; for(var j=0;j<pool.length;j++){ x-=ws[j]; if(x<=0) return pool[j]; } return pool[pool.length-1]; }
function wScore(key,club,gf){
  if(!gf||gf<1) return;
  let cd=(typeof euroClubData==='function'?euroClubData(club):null);
  if((!cd||!cd.r)&&typeof EADB!=='undefined'&&EADB[club]) cd=buildClub(club);
  if(!cd||!cd.r||!cd.r.length) return;
  let roster=cd.r.filter(p=>p.roles&&p.roles[0]!=='POR');
  if(!roster.length) roster=cd.r;
  let att=roster.filter(p=>p.roles&&p.roles.some(r=>['ATT','AS','AD','SP','COC','TC'].includes(r)));
  for(let i=0;i<gf;i++){
    let pool=(att.length&&Math.random()<0.78)?att:roster;
    let s=_wPick(pool); if(!s) continue;
    addCompStat(key,s.name,club,'goals',s.img);
    if(Math.random()<0.55){ let a=_wPick(pool); if(a&&a.name!==s.name) addCompStat(key,a.name,club,'assists',a.img); }
  }
}

function findScorer(teamName, isYou) {
  const fallbackImg = 'https://ui-avatars.com/api/?name=P&background=E2EBF4&color=0D1B2A';
  let roster = [];
  if(isYou) roster = S.draft.xi.filter(p => p && p.roles[0] !== 'POR');
  else if(DB_SERIE_A[teamName]) roster = DB_SERIE_A[teamName].r.filter(p => p.roles[0] !== 'POR');
  else if(ROSTERS_CL[teamName]) roster = ROSTERS_CL[teamName].r.filter(p => p.roles[0] !== 'POR');
  else { let _cd=(typeof euroClubData==='function'?euroClubData(teamName):null)||((typeof EADB!=='undefined'&&EADB[teamName])?buildClub(teamName):null); if(_cd) roster=_cd.r.filter(p=>p.roles[0]!=='POR'); else return { name: `Giocatore`, img: fallbackImg }; }
  if(!roster.length) return { name: `Giocatore`, img: fallbackImg };

  let attackers = roster.filter(p => p.roles.some(r => ['ATT','AS','AD','COC'].includes(r)));
  let pool = (attackers.length > 0 && Math.random() < 0.8) ? attackers : roster;
  let selected = pool[rnd(pool.length)];
  return { name: selected.name, img: selected.img };
}

function syncCupCalendar(){
  try{
    if(!S || !S.calendar || !S.calendar.length) return;
    var cw=S.currentWeek||0;
    var ncDone = !S.nationalCup || S.nationalCup.userOut || !!S.nationalCup.champion;
    if(ncDone){
      S.calendar = S.calendar.filter(function(m,i){ return i<=cw || !(m && m.type==='NC' && !m.played); });
    } else {
      for(var i=cw;i<S.calendar.length;i++){ var m=S.calendar[i]; if(m && m.type==='NC' && !m.played){ if(typeof ensureOpponent==='function'){ try{ensureOpponent(m);}catch(e){} } break; } }
    }
    var koDecided = (S.cl_active_ties!==null && S.cl_active_ties!==undefined);
    if(koDecided){
      var inRace = S.cl_active_ties.some(function(t){ return t && (t.t1===S.teamName||t.t2===S.teamName); });
      var seeded = !!(S.cl_r16_wait && S.cl_r16_wait.indexOf && S.cl_r16_wait.indexOf(S.teamName)>=0);
      if(inRace){
        for(var j=cw;j<S.calendar.length;j++){ var mk=S.calendar[j]; if(mk && typeof mk.type==='string' && mk.type.indexOf('CL_')===0 && mk.type!=='CL_L' && !mk.played){ if(typeof ensureOpponent==='function'){ try{ensureOpponent(mk);}catch(e){} } break; } }
      } else if(!seeded){
        S.calendar = S.calendar.filter(function(m,i){ return i<=cw || !(m && typeof m.type==='string' && m.type.indexOf('CL_')===0 && m.type!=='CL_L' && !m.played); });
      }
    }
  }catch(e){ try{console.warn('syncCupCalendar',e);}catch(_e){} }
}
