  var rounds=[], r1=[], r1win=[];
  ranks.forEach(function(r,gi){ [[4,9],[5,8],[6,7]].forEach(function(pp){ var a=r[pp[0]],b=r[pp[1]],w=_poTie(a,b,true,"c1"+gi+pp[0]); r1.push({a:a,b:b,w:w}); r1win.push({t:w,g:gi,seed:pp[0]}); }); });
  rounds.push({h:"Primo turno \u00b7 Gironi",m:r1});
  var r2=[], r2win=[];
  ranks.forEach(function(r,gi){ var wins=r1win.filter(function(x){return x.g===gi;}); var teams=[{t:r[3],seed:3}].concat(wins).sort(function(x,y){return x.seed-y.seed;}); if(teams.length>=4){ var t1=_poTie(teams[0].t,teams[3].t,true,"c2a"+gi); var t2=_poTie(teams[1].t,teams[2].t,true,"c2b"+gi); r2.push({a:teams[0].t,b:teams[3].t,w:t1}); r2.push({a:teams[1].t,b:teams[2].t,w:t2}); r2win.push(t1); r2win.push(t2); } });
  rounds.push({h:"Secondo turno \u00b7 Gironi",m:r2});
