window.loadExistingTeam = function(club){
  S.usedPlayers = new Set();
  const c = (typeof EADB!=='undefined') ? EADB[club] : null;
  let roster = (c && c.r) ? c.r.map(parseEA) : [];
  roster.sort((a,b)=> (b.rate||0)-(a.rate||0));
  const taken = new Set();
  const pickSlot = (slotRole)=>{
    const grp = ROLE_GROUP[slotRole]||'CEN';
    let idx = roster.findIndex((p,i)=>!taken.has(i) && p.roles.includes(slotRole));
    if(idx<0) idx = roster.findIndex((p,i)=>!taken.has(i) && (ROLE_GROUP[p.roles[0]]||'CEN')===grp);
    if(idx<0) idx = roster.findIndex((p,i)=>!taken.has(i));
    if(idx>=0){ taken.add(idx); return roster[idx]; }
    return genPlayer(slotRole);
  };
  S.draft.xi = FORMATION_SLOTS.map(s=>pickSlot(s.role));
  /* tutta la rosa: il taglio a 12 faceva sparire i giovani, che per
     overall sono sempre gli ultimi */
  S.bench = roster.filter((p,i)=>!taken.has(i));
  S.draft.xi.concat(S.bench).forEach(p=>{ if(p&&p.name) S.usedPlayers.add(p.name); });
  recalcStrength();
  S.budget = startBudget(S.leagueName, S._joinClubStr || S.strength || 72);
  S.euroComp = initialEuroQual(S.leagueName, S._joinClub);
  try{ initFinance(); }catch(e){}
  buildCarrieraSchedule();
  S.screen = "hub"; S.mode = "pano";
  render();
};

/* --- GENERATORE SQUADRA DA ZERO (giovani 16-20, OVR 60-70, nomi casuali) --- */
const GEN_FIRST = ["Luca","Marco","Andrea","Matteo","Davide","Simone","Tommaso","Lorenzo","Federico","Riccardo","Gabriel","Diego","Mateo","Liam","Noah","Hugo","Youssef","Amadou","Kayode","Bryan","Joel","Leo","Iker","Rúben","Tiago","Nikola","Stefan","Emir","Kai","Finn","Théo","Enzo","Nico","Samu","Dani","Pietro","Filippo","Alessandro"];
const GEN_LAST = ["Rossi","Bianchi","Conti","Greco","Bruno","Ferrari","Romano","Marino","Costa","Silva","Santos","Lopez","Garcia","Moreau","Dubois","Müller","Schmidt","Novak","Horvat","Diallo","Traoré","Mensah","Okafor","Andersen","Nielsen","Kovač","Petrović","Yılmaz","Tanaka","Park","Nguyen","De Luca","Esposito","Riva","Vidal","Pavić","Sousa","Lima"];
const GEN_NAT = ["Italy","Spain","France","Germany","Brazil","Argentina","Portugal","Holland","Belgium","Croatia","Serbia","England","Senegal","Nigeria","Japan","Norway","Denmark"];
function genPlayer(role){
  const rate = 52 + rnd(12);            // 52-63 (giovani sconosciuti)
  const age = 16 + rnd(5);              // 16-20
  const name = GEN_FIRST[rnd(GEN_FIRST.length)] + " " + GEN_LAST[rnd(GEN_LAST.length)];
  const base = rate, j = () => Math.max(35, Math.min(85, base - 8 + rnd(17)));
  let pac=j(), sho=j(), pas=j(), dri=j(), def=j(), phy=j();
  if(role==='POR'){ def=base; phy=base; }
  else if(['DC','TD','TS','ED','ES'].includes(role)){ def=Math.min(85,base+rnd(6)); }
  else if(['ATT','AT','AS','AD','COC'].includes(role)){ sho=Math.min(85,base+rnd(6)); pac=Math.min(85,base+rnd(6)); }
  const pot = Math.min(82, rate + 3 + rnd(11)); // margine di crescita realistico (no fenomeni)
  return { name, roles:[role], rate, img: getFace('0', name), pac, sho, pas, dri, def, phy, age, nation: GEN_NAT[rnd(GEN_NAT.length)], pot, height:172+rnd(22), foot:(rnd(100)<24?'Left':'Right'), mv:0, baseRate:rate, gen:true };
}
window.generateScratchTeam = function(){
  S.usedPlayers = new Set();
  S.draft.xi = FORMATION_SLOTS.map(s => genPlayer(s.role));
  // panchina: 7 riserve (un secondo portiere + reparti)
  const benchRoles = ['POR','DC','TD','CC','CDC','AD','ATT'];
  S.bench = benchRoles.map(r => genPlayer(r));
  S.draft.xi.concat(S.bench).forEach(p => S.usedPlayers.add(p.name));
  recalcStrength();
  S.budget = startBudget(S.leagueName, S._joinClubStr || S.strength || 72); // budget in base a lega + prestigio club
  S.euroComp = initialEuroQual(S.leagueName, S._joinClub); // niente Europa se il club non si è qualificato
  try{ initFinance(); }catch(e){}
  buildCarrieraSchedule();
  S.screen = "hub"; S.mode = "pano";
  render();
};

window.generateSpin = function() {
  const clubs = Object.keys(STORIA_CLUB);
  const selectedClub = clubs[rnd(clubs.length)];
  const lastSpace = selectedClub.lastIndexOf(' ');
  S.draft.spinInfo = { club: selectedClub.substring(0, lastSpace), season: selectedClub.substring(lastSpace + 1) };
  S.draft.currentSquad = STORIA_CLUB[selectedClub]; S.draft.selectedPlayerIdx = -1; S.draft.mustSpin = false; render();
};

window.selectPlayer = function(idx) { if (S.draft.mustSpin) return; if (S.usedPlayers.has(S.draft.currentSquad[idx].name)) return; S.draft.selectedPlayerIdx = idx; render(); };
window.placePlayer = function(slotId) {
  if (S.draft.selectedPlayerIdx === -1 || S.draft.mustSpin) return; if (S.draft.xi[slotId] !== null) return;
  const p = S.draft.currentSquad[S.draft.selectedPlayerIdx];
  const reqRole = FORMATION_SLOTS[slotId].role;
  const roleMap = { "POR":["POR"], "DC":["DC"], "TD":["TD","ED","DC"], "TS":["TS","ES","DC"], "CDC":["CDC","CC","DC"], "CC":["CC","CDC","COC"], "AD":["AD","ED","ATT"], "AS":["AS","ES","ATT"], "ATT":["ATT","AT","AS","AD","COC"] };
  let valid = false; for(let r of p.roles) { if(roleMap[reqRole].includes(r)) valid = true; }
  if (!valid) { if(typeof gameMsg==='function'){ gameMsg({title:'Ruolo incompatibile',msg:'<b>'+p.name+'</b> non pu\u00f2 giocare nel ruolo di <b>'+reqRole+'</b>.',icon:'warn'}); } return; }
  S.draft.xi[slotId] = p; S.usedPlayers.add(p.name); S.draft.selectedPlayerIdx = -1; S.draft.mustSpin = true; render();
};

window.doSpin = function() { 
  if(S.draft.xi.every(x => x !== null)) { 
      S.strength = Math.round(S.draft.xi.reduce((acc, p) => acc + p.rate, 0) / 11); 
      buildCarrieraSchedule(); S.screen = "hub"; S.mode = "pano"; 
  } else { 
      generateSpin(); 
  } 
  render(); 
};

window.changeTeamHelp = function() { S.draft.aiutiSquadra--; generateSpin(); };
window.setMode = function(m) { if(m==='cal') S.calMonthOffset = 0; S.mode = m; render(); };
window.closeMod = function() { document.getElementById("m-ov").remove(); S.pending=null; render(); };

