function updateAdvanceOverlay(){ const d=document.getElementById('adv-date'); if(d) d.textContent=cap(new Date(S.currentDay).toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})); }
function stopAdvance(){ if(_advTimer){clearTimeout(_advTimer);_advTimer=null;} const e=document.getElementById('adv-ov'); if(e)e.remove(); _advSkip=false; }
window.skipAdvance=function(){ _advSkip=true; };
window.advanceToDate=function(targetTs, opts){
  if(_advTimer) return;
  _advStopAtMatch = !!(opts && opts.stopAtMatch);
  if(typeof seasonEndTs==='function'){ const _e=seasonEndTs(); if(targetTs>_e) targetTs=_e; }
  if(!S.currentDay){ const ref=S.calendar[Math.min(S.currentWeek,S.calendar.length-1)]; S.currentDay = ref?ref.date:Date.now(); }
  if(!isFinite(targetTs)){ return; }
  if(targetTs<=S.currentDay){ return; }
  _advTarget=targetTs; _advStartOffers=S.offers.length; _advDayAcc=0; _advUps=0; _advGuard=0;
  makeAdvanceOverlay();
  function finish(msg){
    stopAdvance();
    S.calMonthOffset=0;
    if(_advUps>0 && !msg) msg = _advUps+(_advUps>1?' giocatori sono cresciuti':' giocatore \u00e8 cresciuto')+' di OVR! \ud83d\udcc8';
    if(S.offers.length>_advStartOffers){ S.mode='pano'; render(); openOffers(); }
    else render();
    if(msg) showToast(msg);
  }
  function step(){
   try{
    if(++_advGuard>6000){ finish(); return; }
    const m = S.calendar[S.currentWeek];
    const matchTs = m ? m.date : Infinity;
    var _bdoEv=null; try{ _bdoEv=(S.calendar||[]).find(function(x){ return x && x.type==="BDO" && !x.played; }); }catch(e){}
    var _bdoTs=(_bdoEv && _bdoEv.date>S.currentDay)?_bdoEv.date:Infinity;
    const stopTs = Math.min(_advTarget, matchTs);
    let next = S.currentDay + DAY_MS;
    if(next > stopTs) next = stopTs;
    const days = Math.max(1, Math.round((next - S.currentDay)/DAY_MS));
    S.currentDay = next; _advDayAcc += days; if(S.world) simulateWorldUpTo(S.currentDay);
    _advUps += trainTick(days).length;
    if(_advDayAcc>=7){ _advDayAcc=0; maybeGenerateOffers(); }
    updateAdvanceOverlay();
    if(_bdoEv && S.currentDay>=_bdoEv.date){ var _cw=S.currentWeek; var _wasCur=(S.calendar[_cw]===_bdoEv); try{ if(typeof runBallonDor==="function") runBallonDor(_bdoEv,true); else _bdoEv.played=true; }catch(e){ _bdoEv.played=true; } if(!_wasCur) S.currentWeek=_cw; _advTimer=setTimeout(step,0); return; }
    if(m && S.currentDay>=matchTs){
      if(m.type==='BDO'){ if(m.played){ S.currentWeek++; _advTimer=setTimeout(step, 0); return; } try{ if(typeof runBallonDor==='function') runBallonDor(m,true); else { m.played=true; S.currentWeek++; } }catch(e){ m.played=true; S.currentWeek++; } _advTimer=setTimeout(step, 0); return; }
      if(_advStopAtMatch){ finish('\u26bd \u00c8 il giorno della partita!'); return; }
      runSim(true);
      if(S.offers.length>_advStartOffers){ finish('\ud83d\udce9 Nuova offerta ricevuta!'); return; }
      _advTimer=setTimeout(step, _advSkip?0:150); return;
    }
    if(S.offers.length>_advStartOffers){ finish('\ud83d\udce9 Nuova offerta ricevuta!'); return; }
    if(S.currentDay>=_advTarget){ finish(); return; }
    _advTimer=setTimeout(step, _advSkip?0:130);
   }catch(err){ try{console.error('advance error',err);}catch(_e){} finish('\u26a0\ufe0f Avanzamento interrotto da un errore'); }
  }
  step();
};
