  return '<div class="fc-rail">'+logo+'<div class="fc-rail-nav">'+items+'<div class="fc-rail-item kfm-home-item" onclick="kfmHome()" title="Torna alla home"><span class="fc-rail-ic"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 10.6 12 3.2l9 7.4"/><path d="M5.6 9.6V20.8h12.8V9.6"/><path d="M9.9 20.8v-6.1h4.2v6.1"/></svg></span><span class="fc-rail-lb">Home</span></div></div><div class="fc-rail-sp"></div>'+tools+'</div>';
