/* ---------- CALENDARIO (stile immagine 2) ---------- */
function renderCalendario(){
  if(typeof ensurePoStyle==='function')ensurePoStyle();
  const all = S.calendar.filter(e=>e.date);
  if(!all.length) return '<div style="padding:40px;text-align:center;color:var(--ink-light)">Calendario non disponibile.</div>';
  // mese mostrato in base all'offset
  const base = new Date(S.currentDay || S.calendar[Math.min(S.currentWeek,S.calendar.length-1)].date);
  const view = new Date(base.getFullYear(), base.getMonth()+S.calMonthOffset, 1);
  const y=view.getFullYear(), mo=view.getMonth();
  const monthName = cap(view.toLocaleDateString('it-IT',{month:'long',year:'numeric'}));
  const first=new Date(y,mo,1), startDow=(first.getDay()+6)%7; // lun=0
  const days=new Date(y,mo+1,0).getDate();
  const todayTs = S.currentDay || S.calendar[Math.min(S.currentWeek,S.calendar.length-1)].date;
  const byDay={};
  all.forEach(e=>{ const d=new Date(e.date); if(d.getFullYear()===y&&d.getMonth()===mo){ var _ex=byDay[d.getDate()]; byDay[d.getDate()]=(_ex&&_ex.type==='BDO')?_ex:e; } });
  const hist={}; S.history.forEach(h=>{ if(h.date){ const d=new Date(h.date); if(d.getFullYear()===y&&d.getMonth()===mo) hist[d.getDate()]=h; } });

  let cells='';
  for(let i=0;i<startDow;i++) cells+=`<div class="cal-cell empty"></div>`;
  for(let dn=1; dn<=days; dn++){
    const ev=byDay[dn], h=hist[dn];
    const isToday = new Date(todayTs).getDate()===dn && new Date(todayTs).getMonth()===mo;
    let inner=`<div class="cal-num">${dn}</div>`, cls='';
    if(h){ // partita giocata
      if(h.type==='BDO'){ cls='done bdo-day'; inner+=`<div class="cal-ev bdo-ev"><div class="bdo-cal-ic">\ud83c\udfc6</div><span>Pallone d'Oro</span></div>`; }
      else { const cm=calMeta(h.type); cls='done'+(cm.cl?' '+cm.cl:'');
      const r=h.res==='-'?'·':`${h.res} ${h.myGf}-${h.oppGf}`;
      inner+=`<div class="cal-ev"><img src="${h.logo}" onerror="this.style.display='none'"><span class="cal-res ${h.res}">${r}</span><small>${cm.s}</small></div>`; }
    } else if(ev){ // partita futura
      if(ev.type==='BDO'){ cls='next bdo-day'; inner+=`<div class="cal-ev bdo-ev"><div class="bdo-cal-ic">\ud83c\udfc6</div><span>Pallone d'Oro</span></div>`; }
      else { const cm=calMeta(ev.type); cls='next'+(cm.cl?' '+cm.cl:'');
      inner+=`<div class="cal-ev"><img src="${ev.logo||''}" onerror="this.style.display='none'"><span>${ev.home?'Casa':'Trasf.'}</span><small>${cm.s}</small></div>`; }
    }
    if(isToday) cls+=' today';
    const cellTs = new Date(y,mo,dn,23,59,0).getTime();
    const selectable = cellTs > todayTs && cellTs <= (typeof seasonEndTs==='function'?seasonEndTs():Infinity);
    if(S.selCalDay){ const sd=new Date(S.selCalDay); if(sd.getDate()===dn && sd.getMonth()===mo) cls+=' selday'; }
    cells+=`<div class="cal-cell ${cls}" ${selectable?`style="cursor:pointer" onclick="selectCalDay(${cellTs})"`:''}>${inner}</div>`;
  }
  const dows=['L','M','M','G','V','S','D'].map(d=>`<div class="cal-dow">${d}</div>`).join('');
  const nm=S.calendar[Math.min(S.currentWeek,S.calendar.length-1)];
  return `
  <div class="cal-layout">
    <div class="cal-side">
      <div class="cal-side-date">${dayLong(todayTs).toUpperCase()}</div>
      <div class="cal-side-year">${new Date(todayTs).getFullYear()}</div>
      <div class="cal-side-comp">${nm?compLabel(nm.type):''}</div>
      <img class="cal-side-logo" src="${S.userLogo}">
      <div class="cal-side-team">${S.teamName}</div>
      <div class="cal-nav"><button onclick="calNav(-1)">‹</button><span>${monthName}</span><button onclick="calNav(1)">›</button></div>
      ${calAdvancePanel(todayTs)}
    </div>
    <div class="cal-main">
      <div class="cal-dows">${dows}</div>
      <div class="cal-grid">${cells}</div>
    </div>
  </div>`;
}
window.calNav = function(d){ S.calMonthOffset+=d; render(); };

