function marketPool(){
  if(_market) return _market;
  if(!S.transferList && typeof applyTransferLoanLists==='function') applyTransferLoanLists();
  const out=[]; const _seen={};
  for(const cn in EADB){
    /* la tua squadra non si compra da sola: la rosa reale e' quella che
       hai in gestione, non le righe rimaste nel database */
    if(S.teamName && cn===S.teamName) continue;
    for(const line of EADB[cn].r){
      const p=parseEA(line); if(!p||!p.name||!Array.isArray(p.roles)||!p.roles.length) continue; if(S.usedPlayers&&S.usedPlayers.has(p.name)) continue; if(_seen[p.name]) continue; _seen[p.name]=1; p.club=cn; p.price=playerPrice(p); p.grp=ROLE_GROUP[p.roles[0]]||'CEN';
      p.status=(S.transferList&&S.transferList.has(p.name))?'transfer':(S.loanList&&S.loanList.has(p.name))?'loan':'signed';
      if(p.status==='transfer') p.price=Math.max(0.5,Math.round(p.price*0.68*10)/10);
      out.push(p);
    }
  }
  if(S.freeAgents){ for(const line of S.freeAgents){ const p=parseEA(line); if(!p||!p.name||!Array.isArray(p.roles)||!p.roles.length) continue; if(S.usedPlayers&&S.usedPlayers.has(p.name)) continue; if(_seen[p.name]) continue; _seen[p.name]=1; p.club='Svincolato'; p.free=true; p.status='free'; p.price=Math.max(0,Math.round(playerPrice(p)*0.4*10)/10); p.grp=ROLE_GROUP[p.roles[0]]||'CEN'; out.push(p); } }
  _market = out.sort((a,b)=>b.rate-a.rate);
  return _market;
}
function findMarket(name, club){ var pool=marketPool()||[]; var hit=null; if(club){ hit=pool.find(function(x){return x.name===name && x.club===club;}); } return hit || pool.find(function(x){return x.name===name;}) || null; }
/* ====================== CERCA GIOCATORI (filtri stile FC26) ====================== */
function wageBill(){ try{ return Math.round(S.draft.xi.filter(Boolean).concat(S.bench||[]).reduce(function(a,p){ return a + ((p&&(p.wage||playerWage(p)))||0); },0)); }catch(e){ return 0; } }
function annualWages(){ return Math.round(wageBill()*52/1000*10)/10; }
function squadVal(){ try{ return Math.round(S.draft.xi.filter(Boolean).concat(S.bench||[]).reduce(function(a,p){ return a+(p?playerPrice(p):0); },0)); }catch(e){ return 0; } }
function logTx(type,cat,label,amount){ if(!S.finance)S.finance={tx:[]}; if(!S.finance.tx)S.finance.tx=[]; S.finance.tx.unshift({season:S.season, year:getYear(), day:S.currentDay, type:type, cat:cat, label:label, amount:Math.round((amount||0)*100)/100}); if(S.finance.tx.length>150)S.finance.tx.length=150; }
function initFinance(){ S.finance={tx:[]}; S.wageBudget=Math.max(50, Math.round(wageBill()*1.4)); }
function initFinanceWage(){ S.wageBudget=Math.max(S.wageBudget||0, Math.round(wageBill()*1.3)); }
window.cfTab=function(t){ S.searchF.tab=t; render(); };
function cfHubHead(){ if(typeof ensureSF==='function') ensureSF(); var f=S.searchF||{}; return `<div class="cf-head2"><div><h2>MERCATO</h2><div class="cf-tabs2"><span class="${f.tab==='players'?'on':''}" onclick="cfTab('players')">Giocatori</span><span class="${f.tab==='hub'?'on':''}" onclick="cfTab('hub')">Hub mercato</span><span class="${f.tab==='rosa'?'on':''}" onclick="cfTab('rosa')">Mercato Rosa</span></div></div><div class="cf-headr"><div class="mk-budget"><div class="mk-budget-l">Trasferimenti</div><div class="mk-budget-v">\u20ac${S.budget}M</div></div><div class="mk-budget"><div class="mk-budget-l">Ingaggi/sett.</div><div class="mk-budget-v">\u20ac${wageBill()}k</div></div></div></div>`; }
function cfHubBody(){
  var esc=function(s){ return String(s||'').split("'").join(String.fromCharCode(92)+"'"); };
  var Q=String.fromCharCode(39);
  var hub=(S.marketHub||[]).map(function(h){return findMarket(h.name,h.club);}).filter(Boolean);
  if(!hub.length) return '<div class="cf-hubempty">Nessun giocatore nell'+Q+'hub.<br>Apri la scheda di un giocatore e premi \u201cAggiungi all'+Q+'hub\u201d per confrontarlo qui.</div>';
  return hub.map(function(pp){
    var can=S.budget>=pp.price;
    var stats=[['VEL',pp.pac],['TIR',pp.sho],['PAS',pp.pas],['DRI',pp.dri],['DIF',pp.def],['FIS',pp.phy]].map(function(s){ return '<div class="cf-hc-st"><span>'+s[0]+'</span><b>'+(s[1]||'-')+'</b></div>'; }).join('');
    var price=pp.status==='free'?('\u20ac'+playerWage(pp)+'k'):('\u20ac'+pp.price+'M');
    var act=can?('openNegotiate('+Q+esc(pp.name)+Q+',false,'+Q+esc(pp.club||'')+Q+')'):'';
    var btn='<button class="mk-buy '+(can?'':'off')+'" style="width:100%;margin-top:9px;" onclick="event.stopPropagation();'+act+'">'+(pp.status==='free'?'Ingaggia':(can?'Tratta':'\u20ac alto'))+'</button>';
    return '<div class="cf-hubcard" onclick="viewMarketPlayer('+Q+esc(pp.name)+Q+','+Q+esc(pp.club||'')+Q+')"><button class="hubc-x" onclick="event.stopPropagation();toggleHub('+Q+esc(pp.name)+Q+','+Q+esc(pp.club||'')+Q+')">\u00d7</button><img class="cf-hc-face" src="'+pp.img+'" onerror="kfmFaceAvp(this)"><div class="cf-hc-name">'+pp.name+'</div><div class="cf-hc-meta">'+pp.roles.join(', ')+' \u00b7 '+pp.age+' anni</div><div class="cf-hc-meta">'+(pp.club||'Svincolato')+' \u00b7 '+pp.nation+'</div><div class="cf-hc-ovr">'+pp.rate+'</div><div class="cf-hc-price">'+price+'</div><div class="cf-hc-stats">'+stats+'</div>'+btn+'</div>';
  }).join('');
}
function cfHubScreen(){ return `<div class="cf-screen">${cfHubHead()}<div class="cf-hubgrid">${cfHubBody()}</div></div>`; }
window.cfRosaSelect=function(key){ S.rosaSel=key; render(); };
function _rosaClp(v){ v=Math.round(v); return v<1?1:(v>99?99:v); }
function _rosaHash(s){ s=String(s||''); var h=0; for(var i=0;i<s.length;i++){ h=(h*31+s.charCodeAt(i))>>>0; } return h; }
function rosaClubPerf(){ try{ var st=S.saStandings&&S.saStandings[S.teamName]; if(!st) return 60; var arr=Object.keys(S.saStandings).map(function(k){ return S.saStandings[k].pts||0; }).sort(function(a,b){ return b-a; }); var pos=arr.indexOf(st.pts)+1; var tot=arr.length||20; return _rosaClp(90-(pos/tot)*55); }catch(e){ return 60; } }
function rosaMetrics(x){ var p=x&&x.p; if(!p) return {morale:50,forma:50,rendimento:50,minutaggio:50,club:50,contratto:50}; var h=_rosaHash(p.name+(p.pid||'')); var stt=(S.playerStats&&S.playerStats[p.name])||{}; var contrib=(stt.goals||0)+(stt.assists||0); var base=p.rate; var morale = p.listT?28:(p.listL?40:_rosaClp(62+(h%22)+(contrib*2))); var forma = _rosaClp(45+((h>>3)%45)+contrib*3); var minutaggio = _rosaClp(40+((h>>6)%55)); var rendimento = _rosaClp((base-50)*1.4 + contrib*4 + ((h>>9)%18)); var club = rosaClubPerf(); var contratto = _rosaClp(((p.contractYears!=null?p.contractYears:2)>=2)?82:(((p.contractYears||0)>=1)?55:25)); return { morale:morale, forma:forma, rendimento:rendimento, minutaggio:minutaggio, club:club, contratto:contratto }; }
