function _formaWord(v){ return v>=82?'Eccellente':(v>=66?'Buona':(v>=48?'Discreta':(v>=34?'Scarsa':'Pessima'))); }
var _ROSA_POOL={POR:[1,12,13,23],DC:[4,5,6,15,3,2,24],TD:[2,22,24,15],TS:[3,18,15,24],CDC:[6,8,16,14,4],CC:[8,14,18,16,6,10],COC:[10,20,21,8,11],AS:[7,11,17,22,27],AD:[11,7,17,22,27],ATT:[9,19,20,29,30,18]};
function _rosaEnsureShirts(list){ if(!list) list=squadAll(); var used={}; list=(list||[]).filter(function(x){ return x&&x.p; }); list.forEach(function(x){ if(x.p.shirt) used[x.p.shirt]=1; }); list.forEach(function(x){ var p=x.p; if(p.shirt) return; if(typeof SHIRT_DB!=='undefined' && SHIRT_DB[p.name] && !used[SHIRT_DB[p.name]]){ p.shirt=SHIRT_DB[p.name]; used[p.shirt]=1; return; } var role=(p.roles&&p.roles[0])||'CC'; var pool=_ROSA_POOL[role]||[]; for(var i=0;i<pool.length;i++){ if(!used[pool[i]]){ p.shirt=pool[i]; used[pool[i]]=1; return; } } var n=2; while(used[n]&&n<99)n++; p.shirt=n; used[n]=1; }); }
