window.viewPlayerModalBench=function(i){ const p=S.bench[i]; if(p) showPlayerModal(p,false); };
window.rosaTap=function(type, idx){
  const sel=S.rosaSel;
  if(!sel){ if(type==='xi'&&!S.draft.xi[idx]) return; S.rosaSel={type,idx}; render(); return; }
  if(sel.type===type && sel.idx===idx){ S.rosaSel=null; render(); return; } // deseleziona
  // esegui scambio
  if(sel.type==='xi' && type==='xi'){ const a=S.draft.xi[sel.idx]; S.draft.xi[sel.idx]=S.draft.xi[idx]; S.draft.xi[idx]=a; }
  else if(sel.type==='xi' && type==='bench'){ const a=S.draft.xi[sel.idx]; S.draft.xi[sel.idx]=S.bench[idx]; if(a) S.bench[idx]=a; else S.bench.splice(idx,1); }
  else if(sel.type==='bench' && type==='xi'){ const a=S.draft.xi[idx]; S.draft.xi[idx]=S.bench[sel.idx]; if(a) S.bench[sel.idx]=a; else S.bench.splice(sel.idx,1); }
  else if(sel.type==='bench' && type==='bench'){ const a=S.bench[sel.idx]; S.bench[sel.idx]=S.bench[idx]; S.bench[idx]=a; }
  S.rosaSel=null; recalcStrength(); render();
};
window.autoBestXI=function(){
  const all=S.draft.xi.filter(Boolean).concat(S.bench);
  const best=pickBestXI(all);
  S.draft.xi=best.xi.slice(); S.bench=best.bench.slice(); S.rosaSel=null; recalcStrength(); render();
};

