window.makeOffer=function(name){
  const p = marketPool().find(x=>x.name===name); if(!p) return;
  const offer = parseFloat(document.getElementById('neg-offer').value)||0;
  const ask = p.price, msg=document.getElementById('neg-msg'), acc=document.getElementById('neg-accept');
  acc.style.display='none';
  if(offer > S.budget){ msg.textContent='Non hai abbastanza budget per questa cifra.'; msg.className='neg-msg bad'; return; }
  if(offer >= ask){ buyPlayer(name, offer); return; }
  if(offer >= ask*0.88){
    const counter = Math.round(((offer+ask)/2)*10)/10;
    if(S.budget >= counter){ msg.innerHTML=`Quasi! Il club accetta a <b>€${counter}M</b>.`; msg.className='neg-msg';
      acc.style.display='inline-flex'; acc.setAttribute('data-c', counter); acc.textContent=`Accetta €${counter}M`; return; }
  }
  msg.textContent='Offerta rifiutata: troppo bassa. Riprova più in alto.'; msg.className='neg-msg bad';
};
