window.openNegotiate=function(name, skipFee, club, reqLoan){
  const p=findMarket(name, club); if(!p) return;
  if(rosterFull()){ if(typeof gameMsg==='function')gameMsg({title:'Rosa al completo',msg:'La tua rosa ha gi\u00e0 raggiunto il limite di <b>30 giocatori</b>. Cedi qualcuno prima di acquistare.',icon:'club'}); return; }
  { var _ap=p.status||'signed'; if(_ap==='transfer')_ap='signed'; if(_ap==='signed' && S.budget < p.price){ if(typeof gameMsg==='function')gameMsg({title:'Budget insufficiente',msg:'Il cartellino di <b>'+p.name+'</b> costa <b>\u20ac'+p.price+'M</b>, ma il tuo budget \u00e8 di <b>\u20ac'+S.budget+'M</b>. Non puoi avviare la trattativa.',icon:'value'}); return; } }
  let status=p.status||'signed'; if(status==='transfer') status='signed';
  if(reqLoan && status!=='loan'){ if(status==='free'){ if(typeof gameMsg==='function')gameMsg({title:'Gi\u00e0 svincolato',msg:'<b>'+p.name+'</b> \u00e8 svincolato: ingaggialo direttamente, non serve il prestito.',icon:'info'}); return; } var _ch=p.rate>=82?0.18:p.rate>=78?0.4:p.rate>=73?0.62:0.82; if(Math.random()>_ch){ if(typeof gameMsg==='function')gameMsg({title:'Prestito rifiutato',msg:'<b>'+p.club+'</b> rifiuta la richiesta di prestito per <b>'+p.name+'</b>.',icon:'warn'}); return; } status='loan'; if(typeof toast==='function') toast(p.club+' apre al prestito di '+p.name); }
  const _lm=reqLoan?0.16:0.08;
  const startStep=(status==='free')?'wage':(status==='loan')?'loan':(skipFee?'wage':'fee');
  S.neg={ name, status, askFee:p.price, fee:p.price, loanYears:1, loanFee:Math.max(0.5,Math.round(p.price*_lm*10)/10), wageDemand:playerWage(p), wage:playerWage(p), years:(status==='loan'?1:4), step:startStep, sellClub:p.club, rate:p.rate, roles:p.roles.slice(), img:p.img, nation:p.nation, age:p.age, agreedFee:(skipFee&&status==='signed'?p.price:0), finalWage:0, finalFee:0 };
  let ov=document.getElementById('neg-ov'); if(ov) ov.remove();
  ov=document.createElement('div'); ov.className='modal-overlay'; ov.id='neg-ov';
  ov.innerHTML=`<div class="neg-box" id="neg-box"></div>`;
  document.body.appendChild(ov); renderNeg();
};
function closeNeg(){ const ov=document.getElementById('neg-ov'); if(ov) ov.remove(); S.neg=null; }
window.closeNeg=closeNeg;
function renderNeg(){
  const n=S.neg; if(!n) return; const box=document.getElementById('neg-box'); if(!box) return;
  const userCrest=S.userLogo||'';
  const sellCrest=(n.status==='free')?'':((typeof EADB!=='undefined'&&EADB[n.sellClub])?getLogo(EADB[n.sellClub].tid, n.sellClub):'');
  const steps=[]; if(n.status==='signed') steps.push('fee'); if(n.status==='loan') steps.push('loan'); steps.push('wage');
  const labels={fee:'Cartellino',loan:'Prestito',wage:'Ingaggio'};
  const stepIdx=steps.indexOf(n.step);
  const dots=steps.map((s,i)=>{ const done=(n.step==='done')||(i<stepIdx); const cur=s===n.step; return `<div class="neg-dot ${cur?'cur':''} ${done?'done':''}">${done?'\u2713':(i+1)}<b>${labels[s]}</b></div>`; }).join('<div class="neg-line"></div>');
  const cine=`<div class="neg-cine"><div class="neg-shine"></div><div class="neg-crests"><img class="neg-crest" src="${userCrest}" onerror="this.style.visibility='hidden'"><div class="neg-face-wrap"><img class="neg-face" src="${n.img}" onerror="kfmFaceAvp(this)"></div>${n.status==='free'?`<div class="neg-crest neg-freebadge">SVINC.</div>`:`<img class="neg-crest" src="${sellCrest}" onerror="this.style.visibility='hidden'">`}</div><div class="neg-pname">${n.name}</div><div class="neg-psub">${n.roles.join(' \u00b7 ')} \u00b7 OVR ${n.rate} \u00b7 ${n.age} anni \u00b7 ${n.nation}</div></div>`;
  let body='';
  if(n.step==='fee'){
    body=`<div class="neg-r"><span>Richiesta del club (${n.sellClub})</span><b>\u20ac${n.askFee}M</b></div><div class="neg-r"><span>Budget disponibile</span><b>\u20ac${S.budget}M</b></div><div class="neg-r"><span>Clausola rescissoria</span><b style="color:#c79a2e">\u20ac${Math.round(n.askFee*1.6*10)/10}M</b></div><label class="neg-lab">La tua offerta per il cartellino (\u20acM)</label><input id="neg-fee" type="number" min="0" step="0.5" value="${n.fee}" class="neg-input"><div id="neg-msg" class="neg-msg"></div><div class="neg-btns"><button class="neg-go" onclick="negFeeOffer()">Proponi al club \u25b8</button><button class="neg-go" style="background:linear-gradient(180deg,#e8c25a,#b8860b)" onclick="negPayClause()">Paga clausola \u25b8</button></div>`;
  } else if(n.step==='loan'){
    body=`<div class="neg-r"><span>Tipo di accordo</span><b>Prestito secco</b></div><div class="neg-r"><span>Costo del prestito</span><b>\u20ac${n.loanFee}M</b></div><label class="neg-lab">Durata del prestito</label><div class="neg-years">${[1,2].map(y=>`<button class="neg-yr ${n.loanYears===y?'on':''}" onclick="negSetLoan(${y})">${y} ${y===1?'anno':'anni'}</button>`).join('')}</div><div class="neg-note">\u23f1\ufe0f Al termine del prestito il giocatore torner\u00e0 automaticamente a ${n.sellClub}.</div><div id="neg-msg" class="neg-msg"></div><div class="neg-btns"><button class="neg-go" onclick="negConfirmLoan()">Concorda prestito \u25b8</button></div>`;
  } else if(n.step==='wage'){
    const feeRow = n.status==='free' ? `<div class="neg-r"><span>Cartellino</span><b style="color:var(--accent-green,#00A85A)">Gratis \u00b7 svincolato</b></div>` : (n.status==='loan' ? `<div class="neg-r"><span>Costo prestito</span><b>\u20ac${n.loanFee}M (${n.loanYears} ${n.loanYears===1?'anno':'anni'})</b></div>` : `<div class="neg-r"><span>Cartellino concordato</span><b>\u20ac${n.agreedFee||n.fee}M</b></div>`);
    body=`${feeRow}<div class="neg-r"><span>Ingaggio richiesto dall'agente</span><b>\u20ac${n.wageDemand}k/sett.</b></div><label class="neg-lab">La tua offerta d'ingaggio (\u20ack a settimana)</label><input id="neg-wage" type="number" min="0" step="5" value="${n.wage}" class="neg-input">${n.status!=='loan'?`<label class="neg-lab">Durata del contratto</label><div class="neg-years">${[2,3,4,5].map(y=>`<button class="neg-yr ${n.years===y?'on':''}" onclick="negSetYears(${y})">${y} anni</button>`).join('')}</div>`:''}<div id="neg-msg" class="neg-msg"></div><div class="neg-btns"><button class="neg-go" onclick="negWageOffer()">Offri il contratto \u25b8</button></div>`;
  } else {
    body=`<div class="neg-done"><div class="neg-done-ic">\u2705</div><div class="neg-done-t">${n.status==='loan'?'Prestito ufficiale!':'Colpo di mercato!'}</div><div class="neg-done-s">${n.name} ${n.status==='loan'?`arriva in prestito per ${n.loanYears} ${n.loanYears===1?'anno':'anni'}`:'ha firmato con il club'}.<br>Ingaggio \u20ac${n.finalWage}k/sett.${n.status!=='loan'?` \u00b7 contratto ${n.years} anni`:''}${n.finalFee?` \u00b7 cartellino \u20ac${n.finalFee}M`:''}</div><button class="neg-go" onclick="closeNeg();render()">Perfetto \u2713</button></div>`;
  }
  box.innerHTML=`<div class="neg-head"><div class="neg-title">\ud83e\udd1d SALA TRATTATIVE</div><button class="neg-x" onclick="closeNeg()">&times;</button></div>${cine}<div class="neg-steps">${dots}</div><div class="neg-bodyc">${body}</div>`;
}
window.negFeeOffer=function(){ const n=S.neg; if(!n) return; const off=parseFloat(document.getElementById('neg-fee').value)||0; const msg=document.getElementById('neg-msg'); if(off>S.budget){ if(typeof gameMsg==='function')gameMsg({title:'Budget insufficiente',msg:'Non hai abbastanza budget per offrire questa cifra. Disponibili: <b>\u20ac'+S.budget+'M</b>.',icon:'value'}); return; } if(off>=n.askFee){ var _res=Math.round(n.wageDemand*52*2/1000*0.6*10)/10; if(S.budget-off<_res){ if(typeof gameMsg==='function')gameMsg({title:'Fondi insufficienti',msg:'Dopo aver pagato il cartellino non ti resterebbe abbastanza budget per l\'ingaggio del giocatore. Servono pi\u00f9 fondi.',icon:'value'}); return; } n.agreedFee=off; n.fee=off; if(typeof toast==='function')toast('Accordo sul cartellino'); n.step='wage'; renderNeg(); return; } if(off>=n.askFee*0.9){ const c=Math.round(((off+n.askFee)/2)*10)/10; if(c<=S.budget){ msg.innerHTML=`Controproposta del club: <b>\u20ac${c}M</b> &nbsp;<button class="neg-mini" onclick="negAcceptFee(${c})">Accetta</button>`; msg.className='neg-msg'; return; } } msg.textContent='Il club rifiuta: offerta troppo bassa. Rilancia.'; msg.className='neg-msg bad'; };
window.negAcceptFee=function(c){ const n=S.neg; if(!n) return; if(c>S.budget) return; var _res=Math.round(n.wageDemand*52*2/1000*0.6*10)/10; if(S.budget-c<_res){ if(typeof gameMsg==='function')gameMsg({title:'Fondi insufficienti',msg:'Dopo il cartellino non ti resterebbe abbastanza per l\'ingaggio. Servono pi\u00f9 fondi.',icon:'value'}); return; } n.agreedFee=c; n.fee=c; if(typeof toast==='function')toast('Accordo sul cartellino'); n.step='wage'; renderNeg(); };
window.negPayClause=function(){ const n=S.neg; if(!n) return; var clause=Math.round(n.askFee*1.6*10)/10; if(clause>S.budget){ if(typeof gameMsg==='function')gameMsg({title:'Budget insufficiente',msg:'La clausola di <b>'+n.name+'</b> \u00e8 di <b>\u20ac'+clause+'M</b>, superiore al tuo budget (\u20ac'+S.budget+'M).',icon:'value'}); return; } var _res=Math.round(n.wageDemand*52*2/1000*0.6*10)/10; if(S.budget-clause<_res){ if(typeof gameMsg==='function')gameMsg({title:'Fondi insufficienti',msg:'Dopo aver pagato la clausola non ti resterebbe abbastanza per l\'ingaggio del giocatore.',icon:'value'}); return; } n.agreedFee=clause; n.fee=clause; if(typeof toast==='function')toast('Clausola pagata: il club non pu\u00f2 rifiutare'); n.step='wage'; renderNeg(); };
window.negSetLoan=function(y){ const n=S.neg; if(!n) return; n.loanYears=y; n.years=y; renderNeg(); };
window.negConfirmLoan=function(){ const n=S.neg; if(!n) return; if(n.loanFee>S.budget){ const msg=document.getElementById('neg-msg'); if(msg){ msg.textContent='Budget insufficiente per il costo del prestito.'; msg.className='neg-msg bad'; } return; } n.step='wage'; renderNeg(); };
window.negSetYears=function(y){ const n=S.neg; if(!n) return; n.years=y; renderNeg(); };
window.negWageOffer=function(){ const n=S.neg; if(!n) return; const w=parseFloat(document.getElementById('neg-wage').value)||0; const msg=document.getElementById('neg-msg'); if(w<=0){ msg.textContent='Inserisci un ingaggio valido.'; msg.className='neg-msg bad'; return; } if(w>=n.wageDemand){ negFinalize(w); return; } if(w>=n.wageDemand*0.9){ const c=Math.round((w+n.wageDemand)/2); msg.innerHTML=`L'agente chiede <b>\u20ac${c}k/sett.</b> &nbsp;<button class="neg-mini" onclick="negFinalize(${c})">Accetta</button>`; msg.className='neg-msg'; return; } msg.textContent='Ingaggio troppo basso: il giocatore rifiuta. Aumenta la proposta.'; msg.className='neg-msg bad'; };
window.negFinalize=function(w){ const n=S.neg; if(!n) return; if(rosterFull()){ if(typeof gameMsg==='function')gameMsg({title:'Rosa al completo',msg:'La tua rosa ha gi\u00e0 raggiunto il limite di <b>30 giocatori</b>.',icon:'club'}); return; } let fee=0; if(n.status==='signed') fee=n.agreedFee||n.fee; else if(n.status==='loan') fee=n.loanFee; var yrs=(n.status==='loan')?(n.loanYears||1):(n.years||1); var wageTot=Math.round(w*52*yrs/1000*10)/10; var tot=Math.round((fee+wageTot)*10)/10; if(tot>S.budget){ if(typeof gameMsg==='function')gameMsg({title:'Budget insufficiente',msg:'Per chiudere servono <b>\u20ac'+tot+'M</b> (cartellino \u20ac'+fee+'M + ingaggio \u20ac'+wageTot+'M su '+yrs+(yrs===1?' anno':' anni')+'), ma hai solo <b>\u20ac'+S.budget+'M</b>.',icon:'value'}); return; } const p=findMarket(n.name, n.sellClub); if(!p){ closeNeg(); render(); return; } S.budget=Math.round((S.budget-tot)*10)/10; if(typeof logTx==='function'){ if(fee>0)logTx('out','transfer','Acquisto '+n.name,fee); if(wageTot>0)logTx('out','wages','Ingaggio '+n.name+' ('+w+'k/sett \u00b7 '+yrs+(yrs===1?' anno':' anni')+')',wageTot); } _signPlayer(p,{fee, wage:w, years:n.years, loan:(n.status==='loan')}); try{ _fillEmptyXI(); }catch(e){} n.finalWage=w; n.finalFee=fee; n.wageTot=wageTot; n.step='done'; ['p-ov'].forEach(id=>{ const e=document.getElementById(id); if(e) e.remove(); }); renderNeg(); };
window.buyPlayer=function(name, club){ const p=findMarket(name, club); if(!p) return; const st=p.status||'signed'; openNegotiate(name, st!=='loan', p.club); };
function hasSave(){ try{ return !!localStorage.getItem('mgr26save'); }catch(e){ return false; } }
function toast(msg){ try{ const t=document.createElement('div'); t.className='mgr-toast'; t.innerHTML=msg; document.body.appendChild(t); setTimeout(()=>{ t.style.opacity='0'; t.style.transform='translate(-50%,10px)'; setTimeout(()=>t.remove(),400); },1900); }catch(e){} }
function saveGame(){ const mk=()=>{ const c=Object.assign({},S); c.usedPlayers=Array.from(S.usedPlayers||[]); c.transferList=Array.from(S.transferList||[]); c.loanList=Array.from(S.loanList||[]); c.neg=null; return c; }; try{ localStorage.setItem('mgr26save', JSON.stringify({v:3, S:mk(), EADB:(typeof EADB!=='undefined'?EADB:null)})); toast('\ud83d\udcbe Partita salvata'); }catch(e){ try{ localStorage.setItem('mgr26save', JSON.stringify({v:3, S:mk()})); toast('\ud83d\udcbe Salvato (mercato escluso: spazio)'); }catch(e2){ alert('Impossibile salvare: memoria del browser piena.'); } } }
window.saveGame=saveGame;
function loadGame(){ let raw; try{ raw=localStorage.getItem('mgr26save'); }catch(e){ raw=null; } if(!raw){ alert('Nessun salvataggio trovato.'); return; } let blob; try{ blob=JSON.parse(raw); }catch(e){ alert('Salvataggio corrotto.'); return; } const ns=blob.S; if(!ns){ alert('Salvataggio non valido.'); return; } ns.usedPlayers=new Set(ns.usedPlayers||[]); ns.transferList=new Set(ns.transferList||[]); ns.loanList=new Set(ns.loanList||[]); Object.keys(S).forEach(k=>{ if(!(k in ns)) delete S[k]; }); Object.assign(S, ns); if(blob.EADB && typeof EADB!=='undefined'){ Object.keys(EADB).forEach(k=>delete EADB[k]); Object.assign(EADB, blob.EADB); if(typeof buildClub==='function'){ try{ Object.keys(DB_SERIE_A).forEach(cn=>{ if(EADB[cn]) DB_SERIE_A[cn]=buildClub(cn); }); Object.keys(ROSTERS_CL).forEach(cn=>{ if(EADB[cn]) ROSTERS_CL[cn]=buildClub(cn); }); }catch(e){} } } try{ if(typeof MU_repairSave==='function') MU_repairSave(); }catch(e){} _market=null; if(typeof render==='function') render(); toast('\ud83d\udcc2 Partita caricata'); }
window.loadGame=(function(_o){ return function(){ var r=_o.apply(this,arguments);
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  return r; }; })(loadGame);
function calMeta(t){
  if(t==='NC') return {cl:'nc', s:(CUP_SHORT[S.leagueName]||'COPPA')};
  if(t==='SUP') return {cl:'sup', s:'SUPERC.'};
  if(t&&t.indexOf('CL')===0) return {cl:'cl', s:(S.euroComp==='EL'?'EUROPA L.':S.euroComp==='CO'?'CONFER. L.':'CHAMPIONS')};
  return {cl:'', s:(S.leagueName?S.leagueName.toUpperCase():'LEGA')};
}
function renderStats() {
    ensureClassStyle();
    if(!window._clsTeamL){ window._clsTeamL=true; document.addEventListener('click',function(ev){ var el=(ev.target&&ev.target.closest)?ev.target.closest('[data-team]'):null; if(el){ var nm=el.getAttribute('data-team'); if(nm&&typeof viewTeamModal==='function') viewTeamModal(nm); } }); }
    if(!S.statCat) S.statCat='lg';
    let opts=[];
    if(S.statCat==='lg') Object.keys(LEAGUES).forEach(lg=>opts.push({k:'lg:'+lg,lbl:lg}));
    else if(S.statCat==='eu') ['CL','EL','CO'].forEach(c=>opts.push({k:'eu:'+c,lbl:euroCompTab(c)}));
    else Object.keys(CUP_NAMES).forEach(lg=>opts.push({k:'cup:'+lg,lbl:CUP_NAMES[lg]}));
    if(!S.statSel || !opts.some(o=>o.k===S.statSel)) S.statSel = opts.length?opts[0].k:null;
    const cats=[['lg','Campionati'],['eu','Coppe Europee'],['cup','Coppe Nazionali']];
    const pills=cats.map(c=>`<button class="${S.statCat===c[0]?'on':''}" onclick="setStatCat('${c[0]}')">${c[1]}</button>`).join('');
    const selector=`<select class="class-sel" onchange="setStatSel(this.value)">${opts.map(o=>`<option value="${o.k}" ${o.k===S.statSel?'selected':''}>${o.lbl}</option>`).join('')}</select>`;
    const store=(S.compStats&&S.compStats[S.statSel])?S.compStats[S.statSel]:{};
    const entries=Object.entries(store);
    const top=(key)=> entries.map(x=>[x[0],{team:x[1].team,img:x[1].img,val:x[1][key]||0}]).filter(x=>x[1].val>0).sort((a,b)=>b[1].val-a[1].val).slice(0,15);
    const buildCol=(arr,headline)=>`<div class="glass-panel" style="flex:1;min-height:0;"><div class="d-header"><div class="d-title" style="font-size:14px;">${headline}</div></div><div style="overflow-y:auto; max-height:520px;">${arr.map((p,i)=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:12px;border-bottom:1px solid rgba(0,0,0,0.05);cursor:pointer;" data-team="${p[1].team}"><div style="display:flex;align-items:center;gap:12px;"><div style="font-family:'Oswald';color:var(--ink-light);width:15px;">${i+1}</div><img src="${p[1].img}" style="width:36px;height:36px;border-radius:50%;object-fit:cover;" onerror="kfmFaceAvp(this)"><div><div style="font-weight:600;font-size:13px;color:var(--ink-dark);">${p[0]}</div><div style="font-size:10px;color:var(--ink-light);text-transform:uppercase;">${p[1].team}</div></div></div><div style="font-family:'Anton';font-size:20px;color:var(--accent-green);">${p[1].val}</div></div>`).join('') || '<div style="padding:16px;color:var(--ink-light);font-size:12px;">Nessun dato ancora — avanza nella stagione.</div>'}</div></div>`;
    return `<div class="class-head"><div class="class-tabs">${pills}</div>${selector}</div><div style="display:flex;gap:20px;">${buildCol(top('g'),"MARCATORI")} ${buildCol(top('a'),"ASSIST")}</div>`;
}
window.setStatCat=function(c){ S.statCat=c; S.statSel=null; render(); };
window.setStatSel=function(v){ S.statSel=v; render(); };

