/* ===== REGOLAMENTI: budget, qualificazione europea, promozioni/retrocessioni con playoff ===== */
function isTop5League(lg){ return ['Serie A','Premier League','La Liga','Bundesliga','Ligue 1'].indexOf(lg)>=0; }
function _leagueRankByStr(lg, club){ if(!LEAGUES[lg]) return 99; const cs=LEAGUES[lg].filter(c=>EADB[c]); cs.sort((a,b)=>((EADB[b]&&EADB[b].str)||70)-((EADB[a]&&EADB[a].str)||70)); const i=cs.indexOf(club); return i>=0?i+1:99; }
function initialEuroQual(lg, club){ if(!club||!isTop5League(lg)) return null; const r=_leagueRankByStr(lg, club); return qualifyEuro(r); }
function startBudget(lg, str){
  const tier={'Premier League':55,'La Liga':38,'Serie A':38,'Bundesliga':35,'Ligue 1':28,'Eredivisie':14,'Primeira Liga':12,'Süper Lig':14,'Serie B':4,'La Liga 2':3.5,'Ligue 2':3,'Serie C - Girone A':1.6,'Serie C - Girone B':1.6,'Serie C - Girone C':1.6};
  const base=(tier[lg]!=null)?tier[lg]:22;
  const mult=Math.pow(Math.max(0.45,(str||74)/76),3);
  let b=base*mult;
  const isSecond=['Serie B','La Liga 2','Ligue 2','Serie C - Girone A','Serie C - Girone B','Serie C - Girone C'].indexOf(lg)>=0;
  b=Math.max(isSecond?1:3, b);
  return Math.round(b*10)/10;
}
function _finalRank(lg){ let st=(lg===S.leagueName)?S.saStandings:((S.world&&S.world.leagues&&S.world.leagues[lg])?S.world.leagues[lg].standings:null); if(!st) return null; return Object.entries(st).sort((x,y)=>(y[1].pts||0)-(x[1].pts||0)||(y[1].gd||0)-(x[1].gd||0)||(y[1].gf||0)-(x[1].gf||0)).map(e=>e[0]); }
function _simPlayoff(teams){ if(!teams||!teams.length) return null; const pool=teams.map((c,i)=>({c, w:((EADB[c]&&EADB[c].str)||72)+(teams.length-i)*1.2})); let total=pool.reduce((a,p)=>a+Math.pow(p.w,3),0); let r=Math.random()*total; for(const p of pool){ r-=Math.pow(p.w,3); if(r<=0) return p.c; } return pool[0].c; }
function _moveLeague(club, from, to){ if(LEAGUES[from]){ const i=LEAGUES[from].indexOf(club); if(i>=0) LEAGUES[from].splice(i,1); } if(LEAGUES[to] && LEAGUES[to].indexOf(club)<0) LEAGUES[to].push(club); if(club===S.teamName){ S.leagueName=to; S._seasonMove=(['Serie A','La Liga','Ligue 1'].indexOf(to)>=0)?'promossa':'retrocessa'; } }
function doSerieCEnd(){
  try{
    var gir=['Serie C - Girone A','Serie C - Girone B','Serie C - Girone C'];
    var active=gir.filter(function(g){return LEAGUES[g]&&LEAGUES[g].length;});
    if(!active.length) return;
    var userTeam=S.teamName, userGir=(gir.indexOf(S.leagueName)>=0)?S.leagueName:null;
    function st(g){ return (g===S.leagueName)?S.saStandings:((S.world&&S.world.leagues&&S.world.leagues[g])?S.world.leagues[g].standings:null); }
    function pts(g,c){ var s=st(g); return (s&&s[c])?(s[c].pts||0):0; }
    function girOf(c){ for(var i=0;i<gir.length;i++){ if(LEAGUES[gir[i]]&&LEAGUES[gir[i]].indexOf(c)>=0) return gir[i]; } return null; }
    var winners=[], runnersPool=[], releg=[];
    active.forEach(function(g){
      var r=_finalRank(g); if(!r||r.length<6) return;
      winners.push(r[0]);
      for(var i=1;i<Math.min(10,r.length);i++) runnersPool.push(r[i]);
      releg.push(r[r.length-1]);
      [[r.length-5,r.length-2],[r.length-4,r.length-3]].forEach(function(pp){
        var hi=r[pp[0]], lo=r[pp[1]]; if(!hi||!lo) return;
        var gap=pts(g,hi)-pts(g,lo);
        var loser=(gap>8)?lo:(_simPlayoff([hi,lo])===hi?lo:hi);
        releg.push(loser);
      });
    });
    var _scbr=null; try{ _scbr=buildSerieCPlayoff(); }catch(e){} if(!S.poStore)S.poStore={}; if(_scbr) S.poStore['SerieC']=_scbr; var poWin=(_scbr&&_scbr.winner)||_simPlayoff(runnersPool); if(S.poResult && S.poResult.lg===S.leagueName){ poWin = S.poResult.won ? userTeam : (poWin===userTeam ? (runnersPool.filter(function(t){return t!==userTeam;})[0]||poWin) : poWin); }
    var promo=winners.concat(poWin?[poWin]:[]);
    if(!S._serieB) S._serieB=[]; if(!S._serieD) S._serieD=[];
    promo.forEach(function(c){ var fg=girOf(c); if(fg){ var i=LEAGUES[fg].indexOf(c); if(i>=0) LEAGUES[fg].splice(i,1); } if(c!==userTeam && typeof EADB!=='undefined' && EADB[c] && S._serieB.indexOf(c)<0) S._serieB.push(c); });
    releg.forEach(function(c){ var fg=girOf(c); if(fg){ var i=LEAGUES[fg].indexOf(c); if(i>=0) LEAGUES[fg].splice(i,1); } if(c!==userTeam && typeof EADB!=='undefined' && EADB[c] && S._serieD.indexOf(c)<0) S._serieD.push(c); });
    active.forEach(function(g){ var guard=0; while(LEAGUES[g] && LEAGUES[g].length<20 && guard++<90){ var pick=null; if(S._serieD.length) pick=S._serieD.shift(); else if(S._serieB.length) pick=S._serieB.shift(); else break; if(pick && typeof EADB!=='undefined' && EADB[pick] && LEAGUES[g].indexOf(pick)<0) LEAGUES[g].push(pick); } });
    if(userGir){
      var promoSet={}; promo.forEach(function(c){promoSet[c]=1;});
      var relSet={}; releg.forEach(function(c){relSet[c]=1;});
      if(promoSet[userTeam]){ S._promoTo='Serie B'; S._seasonMove='promossa'; if(typeof toast==='function') toast('\u2b06\ufe0f PROMOSSO IN SERIE B! La prossima stagione sali di categoria.'); }
      else if(relSet[userTeam]){ S._seasonMove='retrocessa'; if(typeof toast==='function') toast('\u2b07\ufe0f Retrocesso dalla Serie C.'); }
      else if(typeof toast==='function') toast('\ud83c\udfc1 Stagione di Serie C conclusa: salvezza raggiunta.');
    }
    if(winners.length>=2){ var scWin=_simPlayoff(winners); if(false && userGir && winners.indexOf(userTeam)>=0 && typeof toast==='function'){ toast(scWin===userTeam?'\ud83c\udfc6 Hai vinto la Supercoppa Serie C!':'Supercoppa Serie C: vince '+scWin+'.'); } }
  }catch(e){ if(typeof console!=='undefined') console.warn('doSerieCEnd',e); }
}
function _fixLeagueDupes(){
  if(typeof LEAGUES!=='object'||!LEAGUES) return;
  var mine=S.teamName, keys=Object.keys(LEAGUES), i, j, k, arr, seen={};
  function drop(lg,club){
    try{ if(S.world&&S.world.leagues&&S.world.leagues[lg]&&S.world.leagues[lg].standings)
      delete S.world.leagues[lg].standings[club]; }catch(e){}
  }
  if(mine&&S.leagueName){
    for(i=0;i<keys.length;i++){
      k=keys[i]; if(k===S.leagueName) continue;
      arr=LEAGUES[k]; if(!arr) continue;
      for(j=arr.length-1;j>=0;j--) if(arr[j]===mine){ arr.splice(j,1); }
      drop(k,mine);
    }
    if(LEAGUES[S.leagueName]&&LEAGUES[S.leagueName].indexOf(mine)<0) LEAGUES[S.leagueName].push(mine);
    seen[mine]=S.leagueName;
  }
  for(i=0;i<keys.length;i++){
    k=keys[i]; arr=LEAGUES[k]; if(!arr) continue;
    for(j=arr.length-1;j>=0;j--){
      var c=arr[j];
      if(seen[c]&&seen[c]!==k){ arr.splice(j,1); drop(k,c); }
      else seen[c]=k;
    }
  }
}
function doPromRel(){
  doSerieCEnd();
  const pairs=[['Serie A','Serie B'],['La Liga','La Liga 2'],['Ligue 1','Ligue 2']];
  pairs.forEach(function(pr){ const T=pr[0], B=pr[1]; if(!LEAGUES[T]||!LEAGUES[B]) return; const rt=_finalRank(T), rb=_finalRank(B); if(!rt||!rb||rt.length<6||rb.length<6) return;
    const relegated=rt.slice(-3);
    const auto=rb.slice(0,2);
    let _bbr=null; try{ _bbr=buildBPlayoff(B); }catch(e){} if(!S.poStore)S.poStore={}; if(_bbr) S.poStore[B]=_bbr; const poWin=(_bbr&&_bbr.winner)||_simPlayoff(rb.slice(2,8))||rb[2];
    var _ovw=poWin; if(S.poResult && S.poResult.lg===B){ _ovw = S.poResult.won ? S.teamName : (poWin===S.teamName ? (rb.slice(2,8).filter(function(t){return t!==S.teamName;})[0]||poWin) : poWin); }
    const promoted=auto.concat([_ovw]);
    if(!S._downFrom) S._downFrom={};
    relegated.forEach(function(c){ S._downFrom[c]=B; _moveLeague(c,T,B); });
    if(relegated.indexOf(S.teamName)>=0){ S._relTo=B; }
    promoted.forEach(function(c){ _moveLeague(c,B,T); });
  });
  try{
    if(LEAGUES['Serie B']){
      var _scg=['Serie C - Girone A','Serie C - Girone B','Serie C - Girone C'].filter(function(g){return LEAGUES[g]&&LEAGUES[g].length;});
      if(_scg.length){
        var _rb=_finalRank('Serie B');
        if(_rb&&_rb.length>=6){
          var _dfA=S._downFrom||{};
          var _elig=_rb.filter(function(_t){ return !_dfA[_t]; });
          var _down=_elig.slice(-3);
          _down.forEach(function(cc){
            var g=_scg[Math.floor(Math.random()*_scg.length)];
            var _cand=(LEAGUES[g]||[]).filter(function(t){ return t!==S.teamName && _down.indexOf(t)<0 && typeof EADB!=='undefined' && EADB[t]; });
            _cand.sort(function(a,b){ return ((EADB[b]&&EADB[b].str)||70)-((EADB[a]&&EADB[a].str)||70); });
            var up=_cand[0];
            if(up) _moveLeague(up,g,'Serie B');
            _moveLeague(cc,'Serie B',g);
            if(cc===S.teamName) S._relTo=g;
          });
        }
      }
    }
  }catch(e){ try{ console.warn('serieB releg',e); }catch(_e){} }
  if(typeof _wClubCache!=='undefined' && _wClubCache){ for(const k in _wClubCache) delete _wClubCache[k]; }
  if(S._promoTo){ S.leagueName=S._promoTo; S._promoTo=null; }
  if(S._relTo){ S.leagueName=S._relTo; S._relTo=null; }
  S._downFrom=null;
  try{ _fixLeagueDupes(); }catch(e){ console.warn('dedup',e); }
  if(S._seasonMove && typeof toast==='function'){ toast(S._seasonMove==='promossa'?'⬆️ PROMOSSO! La prossima stagione sali di categoria':'⬇️ Retrocesso: la prossima stagione giochi nella categoria inferiore'); S._seasonMove=null; }
}


/* ===== ROUND 3 (agg.): contratti, rinnovi, selettore nazionalità, supercoppa ===== */
const SUPERCUP_LOGO_API={'Serie A':547,'Premier League':528,'La Liga':556,'Bundesliga':529,'Ligue 1':526,'Eredivisie':525,'Primeira Liga':550,'Süper Lig':551};
/* =======================================================================
   ROUND 9 - PROMOZIONI / RETROCESSIONI RISCRITTE (regole reali FIGC)
   Serie A 20  : 3 retrocesse in Serie B
   Serie B 20  : 2 promosse dirette + 1 dai playoff, 4 retrocesse in Serie C
   Serie C 3x20: 1 promossa per girone + 1 dai playoff (4 in tutto),
                 ultima di ogni girone + perdenti dei playout in Serie D
   Ogni club vive in UNA sola lega e le leghe restano sempre complete.
   ======================================================================= */
var PR_GIR=['Serie C - Girone A','Serie C - Girone B','Serie C - Girone C'];
function _prStand(lg){
  if(lg===S.leagueName) return S.saStandings||null;
  return (S.world&&S.world.leagues&&S.world.leagues[lg])?S.world.leagues[lg].standings:null;
}
function _prStr(c){ return (typeof EADB!=='undefined'&&EADB[c]&&EADB[c].str)||70; }
/* classifica finale: solo i club REALMENTE iscritti a quella lega.
   Se non ci sono dati (mondo non simulato) si ordina per forza, cosi' le
   retrocessioni avvengono sempre e nessuna lega resta bloccata. */
function _prRank(lg){
  var arr=(LEAGUES[lg]||[]).slice(), st=_prStand(lg);
  var hasPts=false;
  if(st){ for(var _k in st){ if(st[_k]&&(st[_k].pts|0)>0){ hasPts=true; break; } } }
  if(!hasPts){                                   /* nessun punto: si ordina per forza */
    arr.sort(function(a,b){ return _prStr(b)-_prStr(a); });
    return arr;
  }
  if(st){
    arr.sort(function(a,b){
      var A=st[a],B=st[b];
      var pa=A?(A.pts|0):-1, pb=B?(B.pts|0):-1;
      if(pb!==pa) return pb-pa;
      var da=A?((A.gf|0)-(A.ga|0)):-999, db=B?((B.gf|0)-(B.ga|0)):-999;
      if(db!==da) return db-da;
      return _prStr(b)-_prStr(a);
    });
  } else arr.sort(function(a,b){ return _prStr(b)-_prStr(a); });
  return arr;
}
function _prDrop(lg,club){
  try{
    if(lg===S.leagueName){ if(S.saStandings) delete S.saStandings[club]; }
    else if(S.world&&S.world.leagues&&S.world.leagues[lg]&&S.world.leagues[lg].standings)
      delete S.world.leagues[lg].standings[club];
  }catch(e){}
}
function _prPull(club){
  var keys=Object.keys(LEAGUES), i, j, arr;
  for(i=0;i<keys.length;i++){
    arr=LEAGUES[keys[i]]; if(!arr) continue;
    for(j=arr.length-1;j>=0;j--) if(arr[j]===club){ arr.splice(j,1); _prDrop(keys[i],club); }
  }
}
/* applica il piano: il club esce da OGNI lista e entra solo nella nuova */
function _prApply(plan){
  for(var c in plan){
    var to=plan[c];
    if(!LEAGUES[to]) continue;
    _prPull(c);
    LEAGUES[to].push(c);
  }
}
/* nessun club in due leghe e nessun "clone" nelle classifiche */
function _prDedupe(){
  var keys=Object.keys(LEAGUES), seen={}, i, j, k, arr;
  if(S.teamName&&S.leagueName&&LEAGUES[S.leagueName]){
    seen[S.teamName]=S.leagueName;
    if(LEAGUES[S.leagueName].indexOf(S.teamName)<0) LEAGUES[S.leagueName].push(S.teamName);
  }
  for(i=0;i<keys.length;i++){
    k=keys[i]; arr=LEAGUES[k]; if(!arr) continue;
    for(j=arr.length-1;j>=0;j--){
      var c=arr[j];
      if(seen[c]&&seen[c]!==k){ arr.splice(j,1); _prDrop(k,c); }
      else seen[c]=k;
    }
  }
  for(i=0;i<keys.length;i++){
    k=keys[i];
    var st=_prStand(k); if(!st) continue;
    var set={}, a=LEAGUES[k]||[];
    for(j=0;j<a.length;j++) set[a[j]]=1;
    for(var cc in st) if(!set[cc]) delete st[cc];
  }
}
function _prWant(k){
  if(k==='Serie A'||k==='Serie B'||PR_GIR.indexOf(k)>=0) return 20;
  if(!S._prSize) S._prSize={};
  var n=(LEAGUES[k]||[]).length;
  if(!S._prSize[k]||n>S._prSize[k]) S._prSize[k]=n;
  return S._prSize[k]||n;
}
/* le leghe non si svuotano mai: esuberi in riserva, buchi riempiti */
function _prNormalize(){
  if(!S._prPool) S._prPool=[];
  var pool=S._prPool, keys=Object.keys(LEAGUES), i, k, arr, used={};
  for(i=0;i<keys.length;i++){
    k=keys[i]; arr=LEAGUES[k]; if(!arr||!arr.length) continue;
    var want=_prWant(k), g1=0;
    while(arr.length>want && g1++<60){
      var cand=arr.filter(function(c){ return c!==S.teamName; });
      cand.sort(function(a,b){ return _prStr(a)-_prStr(b); });
      var out=cand[0]; if(!out) break;
      arr.splice(arr.indexOf(out),1); _prDrop(k,out);
      if(pool.indexOf(out)<0) pool.push(out);
    }
  }
  for(i=0;i<keys.length;i++) (LEAGUES[keys[i]]||[]).forEach(function(c){ used[c]=keys[i]; });
  var reserve=pool.filter(function(c){ return !used[c] && typeof EADB!=='undefined' && EADB[c]; });
  var others=[];
  if(typeof EADB!=='undefined') for(var cn in EADB){ if(!used[cn] && reserve.indexOf(cn)<0) others.push(cn); }
  others.sort(function(a,b){ return _prStr(b)-_prStr(a); });
  for(i=0;i<keys.length;i++){
    k=keys[i]; arr=LEAGUES[k]; if(!arr||!arr.length) continue;
    var w=_prWant(k), tier=(typeof leagueTier==='function')?leagueTier(k):'a', g2=0;
    while(arr.length<w && g2++<90){
      var pick=null;
      if(tier==='a') pick=others.length?others.shift():(reserve.length?reserve.shift():null);
      else pick=reserve.length?reserve.shift():(others.length?others.pop():null);
      if(!pick) break;
      if(used[pick]) continue;
      arr.push(pick); used[pick]=k;
      var pi=pool.indexOf(pick); if(pi>=0) pool.splice(pi,1);
    }
  }
  if(pool.length>140) S._prPool=pool.slice(-140);
}
/* gli svincolati forti non restano liberi per anni: i club li firmano */
function _faTopSign(){
  if(!S.freeAgents||!S.freeAgents.length||typeof EADB==='undefined') return 0;
  var names=Object.keys(EADB), signed=0, i;
  for(i=S.freeAgents.length-1;i>=0;i--){
    var f=String(S.freeAgents[i]).split('|'), nm=f[0], rate=parseInt(f[2],10)||60;
    if(S.faProtected&&S.faProtected[nm]>0) continue;
    if(rate<73) continue;
    if(Math.random()>0.9) continue;
    var cands=names.filter(function(c){
      return c!==S.teamName && EADB[c] && EADB[c].r && EADB[c].r.length<30 &&
             Math.abs(_prStr(c)-rate)<=7;
    });
    if(!cands.length) continue;
    EADB[cands[Math.floor(Math.random()*cands.length)]].r.push(S.freeAgents[i]);
    S.freeAgents.splice(i,1);
    signed++;
  }
  return signed;
}

/* Dopo gli spostamenti va buttato tutto cio' che era costruito sulla
   composizione vecchia: la cache dei club e le classifiche del mondo simulato.
   Senza, le tabelle continuano a mostrare le squadre della stagione passata
   (le retrocesse ancora in Serie A, le neopromosse assenti). */
function _prResync(){
  try{ if(typeof _wClubCache!=='undefined'&&_wClubCache){
    for(var k in _wClubCache) delete _wClubCache[k];
  } }catch(e){}
  try{
    if(S.world&&S.world.leagues){
      for(var lg in S.world.leagues){
        var L=S.world.leagues[lg];
        if(!L) continue;
        if(!LEAGUES[lg]){ delete S.world.leagues[lg]; continue; }
        var st=L.standings||{}, set={}, i;
        for(i=0;i<LEAGUES[lg].length;i++) set[LEAGUES[lg][i]]=1;
        for(var c in st) if(!set[c]) delete st[c];
        for(i=0;i<LEAGUES[lg].length;i++){
          var n=LEAGUES[lg][i];
          if(!st[n]) st[n]={pts:0,gf:0,ga:0,w:0,d:0,l:0,p:0};
        }
        L.standings=st; L.rounds=null; L.rIdx=0;
      }
    }
  }catch(e){ console.warn('_prResync',e); }
}
/* ============================================================================
   IDENTITA' DEL CLUB — perche' la squadra si sdoppiava
   Rinominando il club (per esempio "Juventus" -> "Juve") veniva cambiato solo
   S.teamName: dentro LEAGUES restava il nome vecchio. Da li' in poi il gioco
   trattava le due voci come due squadre diverse. Alla fine della stagione la
   deduplica agganciava il NUOVO nome alla lega giusta e il VECCHIO restava
   dov'era: ecco il clone in Serie A mentre tu sei in Serie B. E siccome la
   lega si ritrovava con una squadra in piu', la normalizzazione ne buttava
   fuori una: sparivano le neopromosse.
   Qui il nome viene cambiato ovunque in una volta sola, e una riparazione
   automatica ricuce i salvataggi gia' rovinati.
   ========================================================================== */
function _clubAllNames(){
  var out={}, k, i, a;
  try{ for(k in LEAGUES){ a=LEAGUES[k]; if(!a) continue;
    for(i=0;i<a.length;i++) out[a[i]]=(out[a[i]]||[]).concat([k]); } }catch(e){}
  return out;
}
/* sostituisce il nome del club in TUTTE le strutture del gioco */
function clubRename(oldN, newN){
  if(!oldN||!newN||oldN===newN) return false;
  var i,k,a,seen;
  try{
    for(k in LEAGUES){
      a=LEAGUES[k]; if(!a) continue;
      for(i=0;i<a.length;i++) if(a[i]===oldN) a[i]=newN;
      seen={};                                  /* via i doppioni nati per strada */
      for(i=a.length-1;i>=0;i--){ if(seen[a[i]]) a.splice(i,1); else seen[a[i]]=1; }
    }
  }catch(e){}
  try{ if(typeof EADB!=='undefined'&&EADB[oldN]){
    if(!EADB[newN]) EADB[newN]=EADB[oldN];
    delete EADB[oldN];
  } }catch(e){}
  try{ if(S.saStandings&&S.saStandings[oldN]){
    if(!S.saStandings[newN]) S.saStandings[newN]=S.saStandings[oldN];
    delete S.saStandings[oldN];
  } }catch(e){}
  try{
    if(S.world&&S.world.leagues) for(var lg in S.world.leagues){
      var st=S.world.leagues[lg]&&S.world.leagues[lg].standings;
      if(st&&st[oldN]){ if(!st[newN]) st[newN]=st[oldN]; delete st[oldN]; }
    }
  }catch(e){}
  try{
    (S.calendar||[]).forEach(function(m){
      if(!m) return;
      if(m.name===oldN) m.name=newN;
      if(m.home===oldN) m.home=newN;
      if(m.away===oldN) m.away=newN;
      if(m.opp===oldN) m.opp=newN;
    });
  }catch(e){}
  try{ if(S._downFrom&&S._downFrom[oldN]){ S._downFrom[newN]=S._downFrom[oldN]; delete S._downFrom[oldN]; } }catch(e){}
  try{ if(S._prPool){ for(i=0;i<S._prPool.length;i++) if(S._prPool[i]===oldN) S._prPool[i]=newN; } }catch(e){}
  return true;
}
/* riparazione: il club dell'utente deve esistere con UN solo nome e in UNA
   sola lega. Si esegue al caricamento e prima di ogni cambio stagione. */
function clubHeal(){
  try{
    if(typeof LEAGUES==='undefined'||!LEAGUES||!S||!S.teamName) return;
    var mine=S.teamName;
    /* 1. se e' rimasto il nome originale del club preso in gestione, si fonde */
    if(S.clubKey && S.clubKey!==mine){
      var names=_clubAllNames();
      if(names[S.clubKey]) clubRename(S.clubKey, mine);
      S.clubKey=mine;
    }
    /* 2. il club deve stare in una lega sola: si tiene quella di S.leagueName */
    var where=[], k, a, i;
    for(k in LEAGUES){
      a=LEAGUES[k]; if(!a) continue;
      for(i=0;i<a.length;i++) if(a[i]===mine){ if(where.indexOf(k)<0) where.push(k); }
    }
    var keep=(S.leagueName&&LEAGUES[S.leagueName])?S.leagueName:(where[0]||null);
    if(keep){
      for(k in LEAGUES){
        a=LEAGUES[k]; if(!a||k===keep) continue;
        for(i=a.length-1;i>=0;i--) if(a[i]===mine){
          a.splice(i,1);
          try{ if(S.world&&S.world.leagues&&S.world.leagues[k]&&S.world.leagues[k].standings)
            delete S.world.leagues[k].standings[mine]; }catch(e){}
        }
      }
      a=LEAGUES[keep];
      var n=0; for(i=a.length-1;i>=0;i--){ if(a[i]===mine){ n++; if(n>1) a.splice(i,1); } }
      if(!n) a.push(mine);
      S.leagueName=keep;
    }
    /* 3. nessun club puo' comparire in due leghe diverse.
          Si scorre partendo dalla lega dell'utente, cosi' e' quella a vincere
          in caso di conflitto. */
    /* si scorre nell'ordine naturale delle leghe (Serie A, poi B, poi C):
       in caso di conflitto vince la categoria piu' alta, che e' quella dove
       il club stava davvero. Il club dell'utente e' gia' stato sistemato al
       punto 2 e qui viene lasciato in pace. */
    var seen={}, order=[];
    for(k in LEAGUES) order.push(k);
    order.forEach(function(kk){
      var arr=LEAGUES[kk]; if(!arr) return;
      for(var j=arr.length-1;j>=0;j--){
        var c=arr[j];
        if(c===mine){ seen[c]=kk; continue; }
        if(seen[c]&&seen[c]!==kk){
          arr.splice(j,1);
          try{ if(S.world&&S.world.leagues&&S.world.leagues[kk]&&S.world.leagues[kk].standings)
            delete S.world.leagues[kk].standings[c]; }catch(e){}
        } else seen[c]=kk;
      }
    });

    /* 4. LE CLASSIFICHE DEVONO RISPECCHIARE GLI ISCRITTI.
          Qui stava il guaio visibile: la tabella della TUA lega si legge da
          S.saStandings, che nessuno ripuliva. Bastava che una squadra ci
          finisse dentro una volta (il Napoli nella tua Serie B) e restava li'
          a schermo per tutta la stagione, con tanto di partite giocate,
          anche se negli elenchi non c'era piu'. Allo stesso modo, le leghe
          simulate mostravano 19 squadre quando ne mancava una in classifica. */
    function _sync(list, st){
      if(!st||!list) return;
      var set={}, q;
      for(q=0;q<list.length;q++) set[list[q]]=1;
      for(var c2 in st) if(!set[c2]) delete st[c2];        /* fuori gli intrusi */
      for(q=0;q<list.length;q++){                          /* dentro chi manca */
        var n2=list[q];
        if(!st[n2]) st[n2]={pts:0,gf:0,ga:0,w:0,d:0,l:0,p:0,g:0,v:0,n:0,pg:0};
      }
    }
    if(S.leagueName&&LEAGUES[S.leagueName]&&S.saStandings)
      _sync(LEAGUES[S.leagueName], S.saStandings);
    if(S.world&&S.world.leagues){
      for(k in S.world.leagues){
        if(!LEAGUES[k]){ delete S.world.leagues[k]; continue; }
        if(k===S.leagueName) continue;
        var L2=S.world.leagues[k];
        if(L2) _sync(LEAGUES[k], L2.standings);
      }
    }
  }catch(e){ console.warn('clubHeal',e); }
}
window.clubRename=clubRename;
window.clubHeal=clubHeal;

function doPromRel(){
  try{
    if(typeof LEAGUES==='undefined'||!LEAGUES) return;
    clubHeal();                                        /* niente cloni in giro */
    var mine=S.teamName, from=S.leagueName, plan={}, toD=[];
    function move(c,to){ if(c&&to&&LEAGUES[to]) plan[c]=to; }

    /* ---- massima serie <-> cadetteria: 3 giu', 2 dirette + 1 playoff su -- */
    [['Serie A','Serie B'],['La Liga','La Liga 2'],['Ligue 1','Ligue 2']].forEach(function(pr){
      var T=pr[0], B=pr[1];
      if(!LEAGUES[T]||!LEAGUES[B]||LEAGUES[T].length<6||LEAGUES[B].length<6) return;
      var rt=_prRank(T), rb=_prRank(B);
      var down=rt.slice(-3), up=rb.slice(0,2), po=null;
      try{ var bb=(typeof buildBPlayoff==='function')?buildBPlayoff(B):null; po=(bb&&bb.winner)||null; }catch(e){}
      if(S.poResult && S.poResult.lg===B && S.poResult.won && mine && rb.indexOf(mine)>=0) po=mine;
      if(!po){ try{ po=(typeof _simPlayoff==='function')?_simPlayoff(rb.slice(2,8)):null; }catch(e){} }
      if(!po) po=rb[2];
      if(po && up.indexOf(po)<0 && down.indexOf(po)<0) up=up.concat([po]);
      down.forEach(function(c){ move(c,B); });
      up.forEach(function(c){ move(c,T); });
    });

    /* ---- Serie B <-> Serie C: 4 giu', 3 vincitrici + 1 playoff su -------- */
    var gir=PR_GIR.filter(function(g){ return LEAGUES[g]&&LEAGUES[g].length>=6; });
    if(LEAGUES['Serie B'] && LEAGUES['Serie B'].length>=6 && gir.length){
      var rB=_prRank('Serie B');
      /* chi e' appena scesa dalla A non retrocede di nuovo nella stessa
         stagione, e chi e' appena salita in A non viene toccata */
      var bDown=rB.filter(function(c){ return !plan[c]; }).slice(-4);
      var cUp=[], poPool=[];
      gir.forEach(function(g){
        var rg=_prRank(g);
        if(rg[0]) cUp.push(rg[0]);
        for(var i=1;i<Math.min(10,rg.length);i++) if(rg[i]) poPool.push(rg[i]);
      });
      try{
        var cb=(typeof buildSerieCPlayoff==='function')?buildSerieCPlayoff():null;
        if(cb){ if(!S.poStore) S.poStore={}; S.poStore['SerieC']=cb; }
      }catch(e){}
      var cPo=null;
      if(S.poResult && PR_GIR.indexOf(S.poResult.lg)>=0 && S.poResult.won) cPo=mine;
      if(!cPo){ try{ cPo=(typeof _simPlayoff==='function')?_simPlayoff(poPool):null; }catch(e){} }
      if(!cPo) cPo=poPool[0];
      if(cPo && cUp.indexOf(cPo)<0) cUp.push(cPo);
      cUp=cUp.slice(0,4);
      /* Serie D: ultima di ogni girone + i perdenti dei playout */
      var playout=[];
      gir.forEach(function(g){
        var rg=_prRank(g).filter(function(c){ return cUp.indexOf(c)<0 && c!==mine; });
        var last=rg[rg.length-1];
        if(last && toD.indexOf(last)<0) toD.push(last);
        rg.slice(-5,-1).forEach(function(c){ if(toD.indexOf(c)<0) playout.push(c); });
      });
      playout.sort(function(a,b){ return _prStr(a)-_prStr(b); });
      playout.slice(0,3).forEach(function(c){ if(toD.indexOf(c)<0) toD.push(c); });
      bDown.forEach(function(c){ move(c,gir[Math.floor(Math.random()*gir.length)]); });
      cUp.forEach(function(c){ move(c,'Serie B'); });
    }

    var dest=plan[mine]||null;
    _prApply(plan);
    if(!S._prPool) S._prPool=[];
    toD.forEach(function(c){
      if(c===mine || plan[c]) return;
      _prPull(c);
      if(S._prPool.indexOf(c)<0) S._prPool.push(c);
    });
    if(dest) S.leagueName=dest;
    S._promoTo=null; S._relTo=null;
    _prDedupe();
    clubHeal();                                        /* prima di riempire i buchi */
    _prNormalize();
    clubHeal();
    _prResync();                                       /* tabelle riallineate a LEAGUES */
    try{ _faTopSign(); }catch(e){}

    if(dest && typeof toast==='function'){
      var tr=function(l){ var t=(typeof leagueTier==='function')?leagueTier(l):'a'; return t==='a'?0:(t==='b'?1:2); };
      var up2=tr(dest)<tr(from);
      S._seasonMove=up2?'promossa':'retrocessa';
      toast(up2?('\u2b06\ufe0f PROMOSSO! La prossima stagione giochi in '+dest)
              :('\u2b07\ufe0f RETROCESSO. La prossima stagione giochi in '+dest));
    }
  }catch(e){ console.warn('doPromRel v2',e); }
}
/* --- lo svincolato firmato NON torna piu' svincolato ogni stagione ------- */
function _muOnRoster(name){
  try{
    if(S.draft&&S.draft.xi) for(var i=0;i<S.draft.xi.length;i++){ var p=S.draft.xi[i]; if(p&&p.name===name) return true; }
    if(S.bench) for(var j=0;j<S.bench.length;j++){ var q=S.bench[j]; if(q&&q.name===name) return true; }
    if(typeof EADB!=='undefined') for(var c in EADB){
      var r=EADB[c]&&EADB[c].r; if(!r) continue;
      for(var k=0;k<r.length;k++) if(String(r[k]).split('|')[0]===name) return true;
    }
  }catch(e){}
  return false;
}

/* ================================================================== */
/* ROUND 13: motore promozioni/retrocessioni ripristinato dalla       */
/* versione funzionante (index2), piu' le protezioni anti-clone.     */
/* Essendo l'ultima dichiarazione di doPromRel, e' questa a valere.   */
/* ================================================================== */
function _r13Heal(){ try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){} }
function _r13Rank(lg){
  var r=null;
  try{ r=(typeof _finalRank==='function')?_finalRank(lg):null; }catch(e){}
  if(r&&r.length) r=r.filter(function(c){ return LEAGUES[lg]&&LEAGUES[lg].indexOf(c)>=0; });
  if(!r||r.length<4){
    /* nessuna classifica salvata: si ordina per forza, cosi' le
       promozioni e le retrocessioni avvengono comunque */
    r=(LEAGUES[lg]||[]).slice().sort(function(a,b){
      var sa=(typeof _prStr==='function')?_prStr(a):70, sb=(typeof _prStr==='function')?_prStr(b):70;
      return sb-sa;
    });
  }
  return r||[];
}
function doPromRel(){
  try{
    if(typeof LEAGUES==='undefined'||!LEAGUES) return;
    _r13Heal();
    var mine=S.teamName, from=S.leagueName;

    /* ---------- Serie C: 3 vincitrici + 1 playoff su, ultime giu' ------- */
    try{ doSerieCEnd(); }catch(e){ console.warn('doSerieCEnd',e); }
    _r13Heal();

    /* ---------- massima serie <-> cadetteria ---------------------------- */
    var pairs=[['Serie A','Serie B'],['La Liga','La Liga 2'],['Ligue 1','Ligue 2']];
    pairs.forEach(function(pr){
      var T=pr[0], B=pr[1];
      if(!LEAGUES[T]||!LEAGUES[B]||!LEAGUES[T].length||!LEAGUES[B].length) return;
      var rt=_r13Rank(T), rb=_r13Rank(B);
      if(rt.length<4||rb.length<4) return;
      /* 3 retrocesse dalla massima serie */
      var down=rt.slice(-3);
      /* 2 promozioni dirette + 1 dai playoff */
      var up=rb.slice(0,2).filter(function(c){ return down.indexOf(c)<0; });
      var po=null;
      try{
        var bb=(typeof buildBPlayoff==='function')?buildBPlayoff(B):null;
        if(bb){ if(!S.poStore) S.poStore={}; S.poStore[B]=bb; po=bb.winner||null; }
      }catch(e){}
      if(S.poResult && S.poResult.lg===B && rb.indexOf(mine)>=0){
        po = S.poResult.won ? mine : (rb.slice(2,8).filter(function(t){ return t!==mine; })[0]||po);
      }
      if(!po){ try{ po=(typeof _simPlayoff==='function')?_simPlayoff(rb.slice(2,8)):null; }catch(e){} }
      if(!po) po=rb[2];
      if(po && up.indexOf(po)<0 && down.indexOf(po)<0) up=up.concat([po]);
      /* prima si svuota la massima serie, poi si inseriscono le promosse:
         un club esce sempre dalla lega di partenza, quindi non si sdoppia */
      down.forEach(function(c){ if(up.indexOf(c)<0) _moveLeague(c,T,B); });
      up.forEach(function(c){ _moveLeague(c,B,T); });
    });

    /* ---------- l'utente segue il suo club ------------------------------ */
    if(S._promoTo){ if(LEAGUES[S._promoTo]) S.leagueName=S._promoTo; S._promoTo=null; }
    if(S._relTo){ if(LEAGUES[S._relTo]) S.leagueName=S._relTo; S._relTo=null; }
    var whereMine=null;
    for(var k in LEAGUES){ var a=LEAGUES[k]; if(a&&a.indexOf(mine)>=0){ whereMine=k; break; } }
    if(whereMine && whereMine!==S.leagueName && !LEAGUES[S.leagueName]) S.leagueName=whereMine;

    /* ---------- pulizia: nessun clone, nessuna lega spaiata ------------- */
    if(typeof _wClubCache!=='undefined' && _wClubCache){ for(var ck in _wClubCache) delete _wClubCache[ck]; }
    _r13Heal();
    try{ if(typeof _prDedupe==='function') _prDedupe(); }catch(e){}
    try{ if(typeof _fixLeagueDupes==='function') _fixLeagueDupes(); }catch(e){}
    _r13Heal();
    /* le leghe tornano sempre a 20 squadre: i gironi non si svuotano */
    try{ if(typeof _prNormalize==='function') _prNormalize(); }catch(e){}
    _r13Heal();
    try{ if(typeof _prResync==='function') _prResync(); }catch(e){}
    try{ if(typeof _faTopSign==='function') _faTopSign(); }catch(e){}

    /* ---------- avviso all'utente -------------------------------------- */
    var to=S.leagueName;
    if(to && from && to!==from){
      var tr=function(l){ var t=(typeof leagueTier==='function')?leagueTier(l):'a'; return t==='a'?0:(t==='b'?1:2); };
      var up2=tr(to)<tr(from);
      S._seasonMove=up2?'promossa':'retrocessa';
      if(typeof toast==='function') toast(up2
        ?('\u2b06\ufe0f PROMOSSO! La prossima stagione giochi in '+to)
        :('\u2b07\ufe0f RETROCESSO. La prossima stagione giochi in '+to));
    } else { S._seasonMove=null; }
  }catch(e){ console.warn('doPromRel r13',e); }
}
/* ==========================================================================
   ROUND 14 - SISTEMA PROMOZIONI / RETROCESSIONI RISCRITTO DA ZERO
   Regolamento reale del calcio italiano (FIGC, stagione 2025/26):
   . Serie A  : 20 squadre, 3 retrocesse in Serie B.
   . Serie B  : 20 squadre. Salgono le prime 2 + 1 dai playoff (dal 3o all'8o).
                Scendono le ultime 3 dirette + 1 dal playout (16a vs 17a) = 4.
   . Serie C  : 3 gironi da 20. Sale la vincente di ogni girone + 1 dai playoff
                = 4 promosse in Serie B. Scendono in Serie D 9 squadre:
                l'ultima di ogni girone + 2 per girone dai playout (16a-19a).
   Il motore RICOSTRUISCE le leghe da zero a ogni cambio stagione:
   ogni club sta in una lega e una sola, ogni lega ha esattamente 20 squadre.
   Cosi' non esistono cloni, squadre che non retrocedono o gironi che si
   svuotano, e le classifiche vengono rigenerate complete (niente undefined).
   ========================================================================== */
var SE_GIR=['Serie C - Girone A','Serie C - Girone B','Serie C - Girone C'];
var SE_PAIRS=[['Serie A','Serie B'],['La Liga','La Liga 2'],['Ligue 1','Ligue 2']];
var SE_ITA={'Serie A':1,'Serie B':1};
SE_GIR.forEach(function(g){ SE_ITA[g]=1; });

function seLg(){ return (typeof LEAGUES!=='undefined'&&LEAGUES)?LEAGUES:null; }
function seStr(c){ try{ return (typeof EADB!=='undefined'&&EADB[c]&&EADB[c].str)||70; }catch(e){ return 70; } }
function seSize(lg){
  if(SE_ITA[lg]) return 20;
  if(!S._seSize) S._seSize={};
  var n=((seLg()&&LEAGUES[lg])||[]).length;
  if(!S._seSize[lg]||n>S._seSize[lg]) S._seSize[lg]=n;
  return S._seSize[lg]||n;
}
function seStand(lg){
  if(lg===S.leagueName) return S.saStandings||null;
  return (S.world&&S.world.leagues&&S.world.leagues[lg])?S.world.leagues[lg].standings:null;
}
/* riga di classifica COMPLETA: e' l'assenza di questi campi che stampava undefined */
function seZero(club){
  var logo='';
  try{ logo=(club===S.teamName)?(S.userLogo||''):((typeof wClub==='function'&&wClub(club))?(wClub(club).logo||''):''); }catch(e){}
  return {p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0,you:club===S.teamName,logo:logo,cs:0};
}
function seSanitize(st){
  if(!st||typeof st!=='object') return st;
  var keys=['p','w','d','l','gf','ga','pts','cs'];
  for(var c in st){
    var t=st[c]; if(!t||typeof t!=='object'){ st[c]=seZero(c); continue; }
    for(var i=0;i<keys.length;i++){ var k=keys[i]; if(typeof t[k]!=='number'||isNaN(t[k])) t[k]=0; }
    t.gd=(t.gf|0)-(t.ga|0);
    if(t.logo===undefined||t.logo===null){ try{ t.logo=(c===S.teamName)?(S.userLogo||''):((typeof wClub==='function'&&wClub(c))?(wClub(c).logo||''):''); }catch(e){ t.logo=''; } }
    if(t.you===undefined) t.you=(c===S.teamName);
  }
  return st;
}
/* classifica finale COMPLETA della lega: chi non ha righe salvate viene messo
   in coda ordinato per forza, cosi' promozioni e retrocessioni avvengono sempre */
function seRank(lg){
  var arr=((seLg()&&LEAGUES[lg])||[]).slice(), st=seStand(lg)||{};
  var seen={}, clean=[];
  arr.forEach(function(c){ if(c&&!seen[c]){ seen[c]=1; clean.push(c); } });
  var have=clean.filter(function(c){ return st[c]; });
  var miss=clean.filter(function(c){ return !st[c]; });
  have.sort(function(a,b){
    var A=st[a]||{}, B=st[b]||{};
    return (B.pts||0)-(A.pts||0) || ((B.gf|0)-(B.ga|0))-((A.gf|0)-(A.ga|0)) || (B.gf||0)-(A.gf||0) || seStr(b)-seStr(a);
  });
  miss.sort(function(a,b){ return seStr(b)-seStr(a); });
  return have.concat(miss);
}
/* sorteggio pesato: conta la forza e il piazzamento in classifica */
function sePick(list){
  list=(list||[]).filter(function(c){ return !!c; });
  if(!list.length) return null;
  var w=[], tot=0, i;
  for(i=0;i<list.length;i++){ var v=Math.pow(seStr(list[i])+(list.length-i)*1.2,3); w.push(v); tot+=v; }
  var r=Math.random()*tot;
  for(i=0;i<list.length;i++){ r-=w[i]; if(r<=0) return list[i]; }
  return list[0];
}
/* playoff promozione: se l'utente li ha giocati vale il risultato vero */
function sePlayoff(list, keys){
  list=(list||[]).filter(function(c){ return !!c; });
  if(!list.length) return null;
  var mine=S.teamName, res=S.poResult;
  try{
    if(res && keys && keys.indexOf(res.lg)>=0 && list.indexOf(mine)>=0){
      if(res.won) return mine;
      list=list.filter(function(c){ return c!==mine; });
    }
  }catch(e){}
  return sePick(list);
}
/* playout salvezza: torna la squadra che retrocede */
function sePlayout(hi, lo){
  if(!hi) return lo||null;
  if(!lo) return null;
  var a=seStr(hi)+2, b=seStr(lo);
  var pa=Math.pow(a,3)/(Math.pow(a,3)+Math.pow(b,3));
  return (Math.random()<pa)?lo:hi;
}
/* --------------------------------------------------------------------------
   riparazione strutturale: un club in una lega sola, leghe della giusta
   dimensione, classifiche allineate e complete
   -------------------------------------------------------------------------- */
function seDedupe(){
  if(!seLg()) return;
  var mine=S.teamName, seen={}, keys=Object.keys(LEAGUES), i, j, a, k;
  /* il club dell'utente vince sempre sulla lega dichiarata in S.leagueName */
  if(mine && LEAGUES[S.leagueName]) seen[mine]=S.leagueName;
  for(i=0;i<keys.length;i++){
    k=keys[i]; a=LEAGUES[k]; if(!a) continue;
    for(j=a.length-1;j>=0;j--){
      var c=a[j];
      if(!c){ a.splice(j,1); continue; }
      if(seen[c]===undefined){ seen[c]=k; continue; }
      if(seen[c]!==k || a.indexOf(c)!==j){
        a.splice(j,1);
        try{ var st=seStand(k); if(st) delete st[c]; }catch(e){}
      }
    }
  }
  if(mine && LEAGUES[S.leagueName] && LEAGUES[S.leagueName].indexOf(mine)<0) LEAGUES[S.leagueName].push(mine);
}
function seReserve(){ if(!S._seD) S._seD=[]; return S._seD; }
/* riporta ogni lega alla sua dimensione: esuberi in riserva, buchi riempiti */
function seBalance(onlyIta){
  if(!seLg()) return;
  var res=seReserve(), used={}, keys=Object.keys(LEAGUES), i, k, a;
  for(i=0;i<keys.length;i++) (LEAGUES[keys[i]]||[]).forEach(function(c){ used[c]=keys[i]; });
  for(i=0;i<keys.length;i++){
    k=keys[i]; if(onlyIta && !SE_ITA[k]) continue;
    a=LEAGUES[k]; if(!a||!a.length) continue;
    var want=seSize(k), g=0;
    while(a.length>want && g++<80){
      var cand=a.filter(function(c){ return c!==S.teamName; });
      cand.sort(function(x,y){ return seStr(x)-seStr(y); });
      var out=cand[0]; if(!out) break;
      a.splice(a.indexOf(out),1);
      try{ var st=seStand(k); if(st) delete st[out]; }catch(e){}
      delete used[out];
      if(res.indexOf(out)<0) res.push(out);
    }
  }
  var pool=res.filter(function(c){ return !used[c] && typeof EADB!=='undefined' && EADB[c]; });
  var extra=[];
  try{ if(typeof EADB!=='undefined') for(var cn in EADB){ if(!used[cn] && pool.indexOf(cn)<0) extra.push(cn); } }catch(e){}
  /* un campionato si riempie solo con club dello stesso paese: senza questo
     filtro in Serie B finivano Cruzeiro, Santos e le altre brasiliane */
  function sePaese(c){ try{ return (EADB[c]&&EADB[c].country)||''; }catch(e){ return ''; } }
  function sePaeseLega(lg){
    try{ if(typeof LEAGUE_COUNTRY!=='undefined' && LEAGUE_COUNTRY[lg]) return LEAGUE_COUNTRY[lg]; }catch(e){}
    var a=LEAGUES[lg]||[];
    for(var q=0;q<a.length;q++){ var p=sePaese(a[q]); if(p) return p; }
    return '';
  }
  var SE_PAESE_IT={'Italia':'Italy','Inghilterra':'England','Spagna':'Spain','Germania':'Germany',
    'Francia':'France','Olanda':'Netherlands','Portogallo':'Portugal','Turchia':'Turkey',
    'Belgio':'Belgium','Brasile':'Brazil','Argentina':'Argentina','Messico':'Mexico',
    'Stati Uniti':'United States','Giappone':'Japan','Corea del Sud':'South Korea','Cina':'China',
    'Grecia':'Greece','Scozia':'Scotland','Svizzera':'Switzerland','Austria':'Austria',
    'Croazia':'Croatia','Danimarca':'Denmark','Norvegia':'Norway','Svezia':'Sweden',
    'Polonia':'Poland','Russia':'Russia','Ucraina':'Ukraine','Egitto':'Egypt','Arabia Saudita':'Saudi Arabia'};
  function seCompatibile(c,lg){
    var pl=sePaeseLega(lg); if(!pl) return true;
    var pc=sePaese(c);
    /* club senza paese (campionati non scaricati) fuori: era cosi' che
       il Kerala Blasters finiva in Serie B */
    if(!pc) return false;
    var pl2=SE_PAESE_IT[pl]||pl;
    return pc===pl2;
  }
  extra.sort(function(x,y){ return seStr(y)-seStr(x); });
  for(i=0;i<keys.length;i++){
    k=keys[i]; if(onlyIta && !SE_ITA[k]) continue;
    a=LEAGUES[k]; if(!a||!a.length) continue;
    var w2=seSize(k), tier=(typeof leagueTier==='function')?leagueTier(k):'a', g2=0;
    while(a.length<w2 && g2++<80){
      var pick=null;
      var okPool=pool.filter(function(c){ return seCompatibile(c,k); });
      var okExtra=extra.filter(function(c){ return seCompatibile(c,k); });
      if(tier==='a') pick=okExtra.length?okExtra[0]:(okPool.length?okPool[0]:null);
      else pick=okPool.length?okPool[0]:(okExtra.length?okExtra[okExtra.length-1]:null);
      if(!pick) break;   /* nessun club dello stesso paese: la lega resta com'e' */
      if(pick){ var ip=pool.indexOf(pick); if(ip>=0) pool.splice(ip,1);
                var ie=extra.indexOf(pick); if(ie>=0) extra.splice(ie,1); }
      if(!pick) break;
      if(used[pick]) continue;
      a.push(pick); used[pick]=k;
      var pi=res.indexOf(pick); if(pi>=0) res.splice(pi,1);
    }
  }
  S._seD=res.filter(function(c){ return !used[c]; }).slice(-160);
}
/* classifiche riallineate alle leghe, righe complete */
function seResync(){
  try{ if(typeof _wClubCache!=='undefined'&&_wClubCache){ for(var ck in _wClubCache) delete _wClubCache[ck]; } }catch(e){}
  if(!seLg()) return;
  try{
    if(S.leagueName&&LEAGUES[S.leagueName]&&S.saStandings){
      var set={}, arr=LEAGUES[S.leagueName], i;
      for(i=0;i<arr.length;i++) set[arr[i]]=1;
      for(var c in S.saStandings) if(!set[c]) delete S.saStandings[c];
      for(i=0;i<arr.length;i++) if(!S.saStandings[arr[i]]) S.saStandings[arr[i]]=seZero(arr[i]);
      seSanitize(S.saStandings);
    }
    if(S.world&&S.world.leagues){
      for(var lg in S.world.leagues){
        var L=S.world.leagues[lg];
        if(!L) continue;
        if(!LEAGUES[lg]){ delete S.world.leagues[lg]; continue; }
        var st=L.standings||{}, s2={}, arr2=LEAGUES[lg], j;
        for(j=0;j<arr2.length;j++) s2[arr2[j]]=1;
        for(var c2 in st) if(!s2[c2]) delete st[c2];
        for(j=0;j<arr2.length;j++) if(!st[arr2[j]]) st[arr2[j]]=seZero(arr2[j]);
        seSanitize(st);
        L.standings=st; L.clubs=arr2.slice(); L.rounds=null; L.rIdx=0;
      }
    }
  }catch(e){ console.warn('seResync',e); }
}
function seRepair(){
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  try{ seDedupe(); }catch(e){}
  try{ seBalance(true); }catch(e){}
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  try{ seResync(); }catch(e){}
}
/* --------------------------------------------------------------------------
   fine stagione: verdetti e ricostruzione delle categorie
   -------------------------------------------------------------------------- */
function seasonEnd(){
  if(!seLg()) return;
  var mine=S.teamName, from=S.leagueName;
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  seDedupe();

  /* mappa attuale club -> lega */
  var map={}, keys=Object.keys(LEAGUES), i;
  for(i=0;i<keys.length;i++) (LEAGUES[keys[i]]||[]).forEach(function(c){ if(map[c]===undefined) map[c]=keys[i]; });
  if(mine && LEAGUES[from]) map[mine]=from;

  var move={}, toD=[], verdict={up:[],down:[]};
  function mv(c,lg){ if(c&&lg&&LEAGUES[lg]) move[c]=lg; }

  /* ---------- massima serie <-> cadetteria (Italia, Spagna, Francia) ------ */
  SE_PAIRS.forEach(function(pr){
    var T=pr[0], B=pr[1];
    if(!LEAGUES[T]||!LEAGUES[B]) return;
    var rt=seRank(T), rb=seRank(B);
    if(rt.length<6||rb.length<6) return;
    var down=rt.slice(-3);                                   /* 3 retrocesse */
    var up=rb.slice(0,2).slice();                            /* 2 promosse dirette */
    var po=null;
    try{ var bb=(typeof buildBPlayoff==='function')?buildBPlayoff(B):null;
         if(bb){ if(!S.poStore) S.poStore={}; S.poStore[B]=bb; po=bb.winner||null; } }catch(e){}
    var pool=rb.slice(2,8);
    if(po && pool.indexOf(po)<0) po=null;
    if(S.poResult && S.poResult.lg===B && pool.indexOf(mine)>=0) po=null;   /* decide il risultato vero */
    if(!po) po=sePlayoff(pool,[B]);
    if(po && up.indexOf(po)<0) up.push(po);
    up=up.filter(function(c){ return down.indexOf(c)<0; });
    down.forEach(function(c){ if(up.indexOf(c)<0) mv(c,B); });
    up.forEach(function(c){ mv(c,T); });
    if(T==='Serie A'){ verdict.down=verdict.down.concat(down); verdict.up=verdict.up.concat(up); }
  });

  /* ---------- Serie B -> Serie C: 3 dirette + 1 playout ------------------ */
  var gir=SE_GIR.filter(function(g){ return LEAGUES[g]&&LEAGUES[g].length>=6; });
  var bDown=[];
  if(LEAGUES['Serie B'] && LEAGUES['Serie B'].length>=8 && gir.length){
    var rb2=seRank('Serie B').filter(function(c){ return move[c]!=='Serie A'; });   /* le promosse non retrocedono */
    bDown=rb2.slice(-3);
    var hi=rb2[rb2.length-5], lo=rb2[rb2.length-4];
    var loser=sePlayout(hi,lo);
    if(loser && bDown.indexOf(loser)<0) bDown.push(loser);                          /* 4 retrocesse in totale */
  }

  /* ---------- Serie C -> Serie B: 3 vincenti + 1 playoff ----------------- */
  var cUp=[], poPool=[];
  if(gir.length){
    gir.forEach(function(g){
      var rg=seRank(g);
      if(rg[0]) cUp.push(rg[0]);
      for(var k=1;k<Math.min(10,rg.length);k++) if(rg[k]) poPool.push(rg[k]);
    });
    try{ var cb=(typeof buildSerieCPlayoff==='function')?buildSerieCPlayoff():null;
         if(cb){ if(!S.poStore) S.poStore={}; S.poStore['SerieC']=cb; } }catch(e){}
    var cPo=sePlayoff(poPool,SE_GIR);
    if(cPo && cUp.indexOf(cPo)<0) cUp.push(cPo);
    cUp=cUp.slice(0,4);

    /* ---------- Serie C -> Serie D: ultima + 2 playout per girone -------- */
    gir.forEach(function(g){
      var rg=seRank(g).filter(function(c){ return cUp.indexOf(c)<0; });
      if(rg.length<6) return;
      var last=rg[rg.length-1];
      if(last && toD.indexOf(last)<0) toD.push(last);
      var po1=sePlayout(rg[rg.length-5], rg[rg.length-2]);   /* 16a vs 19a */
      var po2=sePlayout(rg[rg.length-4], rg[rg.length-3]);   /* 17a vs 18a */
      [po1,po2].forEach(function(c){ if(c && toD.indexOf(c)<0) toD.push(c); });
    });
  }
  /* le 4 scese dalla B entrano nei gironi, le 4 promosse salgono in B */
  bDown.forEach(function(c,idx){ mv(c, gir.length?gir[idx%gir.length]:null); });
  cUp.forEach(function(c){ mv(c,'Serie B'); });

  /* ---------- Serie D -> Serie C: sale la prima di ogni girone -----------
     Regolamento vero: promozione diretta alla vincitrice del girone; dalla
     2a alla 5a si giocano i playoff, che non promuovono ma stilano la
     graduatoria per i ripescaggi. Sotto la Serie D qui non c'e' niente,
     quindi nessuno esce: chi scende dalla C prende il posto di chi sale. */
  /* ---------- altre piramidi: Inghilterra e Brasile ----------
     Inghilterra: 3 su e 3 giu' fra Premier, Championship, League One e
     League Two; sotto la League Two non c'e' niente, come per la Serie D.
     Brasile: 4 su e 4 giu' fra Serie A, B e C.                        */
  [{lv:['Premier League','Championship','League One','League Two'],n:3},
   {lv:['Brasileir\u00e3o S\u00e9rie A','Brasileir\u00e3o S\u00e9rie B','Brasileir\u00e3o S\u00e9rie C'],n:4}]
  .forEach(function(P){
    for(var i=0;i<P.lv.length-1;i++){
      var alta=P.lv[i], bassa=P.lv[i+1];
      if(!LEAGUES[alta]||!LEAGUES[bassa]) continue;
      var ra=seRank(alta), rb=seRank(bassa);
      if(!ra.length||!rb.length) continue;
      ra.slice(-P.n).forEach(function(c){ if(!move[c]) mv(c,bassa); });   /* retrocesse */
      rb.slice(0,P.n).forEach(function(c){ if(!move[c]) mv(c,alta); });   /* promosse */
    }
  });

  var girD = Object.keys(LEAGUES).filter(function(g){
    return g.indexOf('Serie D - Girone')===0 && LEAGUES[g] && LEAGUES[g].length>=6;
  }).sort();
  var dUp=[];
  if(girD.length && gir.length){
    girD.forEach(function(g){
      var rd=seRank(g);
      if(rd[0]) dUp.push(rd[0]);
      /* tabellone playoff del girone: 2a-5a, solo per la graduatoria */
      try{
        var po=rd.slice(1,5);
        if(po.length===4){
          if(!S.poStore) S.poStore={};
          if(!S.poStoreD) S.poStoreD={};
          S.poStoreD[g]={ girone:g, squadre:po,
            preliminare:[po[2],po[3]], semifinale:po[1], finale:po[0],
            vincitore:sePlayoff(po,[g]) };
        }
      }catch(e){}
    });
    /* le promosse si spalmano sui tre gironi di Serie C */
    dUp.forEach(function(c,idx){ mv(c, gir[idx%gir.length]); });
    /* e le retrocesse dalla C scendono nei gironi di Serie D */
    toD.forEach(function(c,idx){ if(!move[c]) mv(c, girD[idx%girD.length]); });
    toD=[];   /* gestite qui: non finiscono in riserva */
  }

  /* ---------- applicazione: si riscrive la mappa e poi le leghe ---------- */
  for(var c3 in move) map[c3]=move[c3];
  var res=seReserve();
  toD.forEach(function(c){
    if(move[c]) return;                    /* chi e' stato promosso non scende */
    delete map[c];
    if(res.indexOf(c)<0) res.push(c);
  });
  /* chi torna dalla Serie D non resta in riserva se e' stato ripescato */
  for(var c4 in map){ var ri=res.indexOf(c4); if(ri>=0) res.splice(ri,1); }

  var bucket={};
  keys=Object.keys(LEAGUES);
  for(i=0;i<keys.length;i++) bucket[keys[i]]=[];
  Object.keys(map).forEach(function(c){ var lg=map[c]; if(bucket[lg] && bucket[lg].indexOf(c)<0) bucket[lg].push(c); });
  for(i=0;i<keys.length;i++){
    var k2=keys[i];
    if(!bucket[k2].length) continue;                 /* leghe non gestite: intatte */
    LEAGUES[k2].length=0;
    bucket[k2].forEach(function(c){ LEAGUES[k2].push(c); });
  }

  /* la squadra dell'utente segue la sua categoria */
  var dest=map[mine]||from;
  if(dest && LEAGUES[dest]){
    S.leagueName=dest;
    if(LEAGUES[dest].indexOf(mine)<0) LEAGUES[dest].push(mine);
  }
  S._promoTo=null; S._relTo=null;

  seDedupe();
  seBalance(false);
  /* registro chi e' salito e chi e' sceso, per mostrarlo nel tabellone */
  try{
    S._movimenti = { stagione: (typeof getYear==='function'? getYear() : S.season), su: [], giu: [] };
    for(var _c in move){
      var _da=(mapPrec&&mapPrec[_c])||'', _a=move[_c];
      if(!_a || _da===_a) continue;
      var _r={ club:_c, da:_da, a:_a };
      (function(){
        var ord=['Serie A','Serie B','Serie C','Serie D'];
        function liv(x){ for(var i=0;i<ord.length;i++) if(String(x).indexOf(ord[i])===0) return i; return 9; }
        if(liv(_a) < liv(_da)) S._movimenti.su.push(_r); else S._movimenti.giu.push(_r);
      })();
    }
  }catch(e){}                                  /* ogni lega torna a 20 */
  try{ if(typeof clubHeal==='function') clubHeal(); }catch(e){}
  seResync();
  try{ if(typeof _faTopSign==='function') _faTopSign(); }catch(e){}

  /* ---------- messaggi ---------- */
  try{
    if(dest && from && dest!==from){
      var tr=function(l){ var t=(typeof leagueTier==='function')?leagueTier(l):'a'; return t==='a'?0:(t==='b'?1:2); };
      var up2=tr(dest)<tr(from);
      S._seasonMove=up2?'promossa':'retrocessa';
      if(typeof toast==='function') toast(up2
        ?('\u2b06\ufe0f PROMOSSO! La prossima stagione giochi in '+dest)
        :('\u2b07\ufe0f RETROCESSO. La prossima stagione giochi in '+dest));
    } else {
      S._seasonMove=null;
      if(from==='Serie A' && verdict.down.length && typeof toast==='function')
        toast('\ud83c\udfc1 Retrocesse in Serie B: '+verdict.down.join(', '));
    }
  }catch(e){}
}
