function processContracts(){
  const leaving=[];
  const dec=(p)=>{ if(!p||p.loaned) return true; if(p._renewed){ p._renewed=false; if(p.contractYears==null) p.contractYears=2; return true; } if(p.contractYears==null) p.contractYears=3; p.contractYears-=1; return p.contractYears>0; };
  S.draft.xi.forEach((p,i)=>{ if(p && !dec(p)){ leaving.push(p); S.draft.xi[i]=null; } });
  S.bench=S.bench.filter(p=>{ if(!p) return false; if(p.loaned) return true; if(!dec(p)){ leaving.push(p); return false; } return true; });
  leaving.forEach(p=>{ if(S.usedPlayers) S.usedPlayers.delete(p.name); try{ if(typeof removePlayerFromAllClubs==='function') removePlayerFromAllClubs(p.name); }catch(e){} if(!S.freeAgents) S.freeAgents=[]; S.freeAgents.push(playerToLine(p)); if(!S.faProtected) S.faProtected={}; S.faProtected[p.name]=1; });
  if(leaving.length && typeof toast==='function') toast('📄 '+leaving.length+' giocatore/i a fine contratto ha/hanno lasciato il club a parametro zero.');
  if(typeof recalcStrength==='function') recalcStrength();
}
