function natFlag(name){ const c=NATION_FLAG[name]; return c?('https://flagcdn.com/w80/'+c+'.png'):''; }
function natAvatar(n){ try{ var t=String(n||'?').slice(0,2).toUpperCase().replace(/[^A-Z]/g,''); if(!t) t='?'; var svg="<svg xmlns='http://www.w3.org/2000/svg' width='64' height='44'><rect width='64' height='44' rx='5' fill='#2b6df7'/><text x='32' y='30' font-family='Arial,Helvetica,sans-serif' font-size='20' font-weight='bold' fill='#ffffff' text-anchor='middle'>"+t+"</text></svg>"; return 'data:image/svg+xml;base64,'+btoa(svg); }catch(e){ return AVT; } }
function normalizeNation(n){ if(!n) return n; n=String(n).trim(); if(/Ivoir/i.test(n)||/Ivory/i.test(n)) return "Côte d'Ivoire"; if(n.indexOf('\uFFFD')>=0){ n=n.replace(/\uFFFD+/g,'').trim(); } return n; }
function allNations(){ const set=new Set(); const add=(raw)=>{ const n=normalizeNation(raw); if(n) set.add(n); }; if(typeof EADB!=='undefined'){ for(const cn in EADB){ const club=EADB[cn]; if(!club||!club.r) continue; for(const line of club.r){ add(String(line).split('|')[6]); } } } (S.freeAgents||[]).forEach(l=>{ add(String(l).split('|')[6]); }); return Array.from(set).filter(Boolean).sort(); }
function _natTiles(list){
  window._natShown=list;
  let html=`<div class="nat-tile" onclick="setSF('nat','');closePick()"><div class="nat-flag" style="display:flex;align-items:center;justify-content:center;font-size:24px;background:rgba(0,0,0,.05);">🌍</div><div class="nat-name">Qualsiasi</div></div>`;
  html+=list.map((n,i)=>{ const fl=natFlag(n)||natAvatar(n); return `<div class="nat-tile" onclick="setSF('nat',window._natShown[${i}]);closePick()"><img class="nat-flag" loading="lazy" referrerpolicy="no-referrer" src="${fl}" onerror="this.onerror=null;this.src='${natAvatar(n)}'"><div class="nat-name">${n}</div></div>`; }).join('');
  return html;
}
function ensureNatStyle(){ if(document.getElementById('nat-style')) return; const s=document.createElement('style'); s.id='nat-style'; s.textContent='.nat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:10px;padding:8px 2px;max-height:58vh;overflow:auto;}.nat-tile{display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 6px;border-radius:12px;cursor:pointer;background:rgba(0,0,0,.03);transition:.15s;text-align:center;}.nat-tile:hover{background:rgba(43,109,247,.14);transform:translateY(-2px);}.nat-flag{width:48px;height:32px;object-fit:cover;border-radius:5px;box-shadow:0 1px 5px rgba(0,0,0,.25);}.nat-name{font-size:11px;color:var(--ink-dark);font-weight:600;line-height:1.15;word-break:break-word;}'; document.head.appendChild(s); }
window._natList=[];
window._natShown=[];
window.openSearchNat=function(){
  window._natList=allNations(); ensureNatStyle();
  const ov=document.createElement('div'); ov.className='modal-overlay'; ov.id='pick-ov';
  ov.innerHTML=`<div class="modal-box pick-box"><div class="m-header"><div style="font-family:'Oswald';letter-spacing:1px;color:var(--ink-dark);">Seleziona nazionalità</div><button onclick="closePick()" style="font-size:24px;color:var(--ink-mid);line-height:1;">&times;</button></div><input id="nat-search" class="pick-search" placeholder="Cerca nazione..." oninput="natFilter(this.value)"><div class="nat-grid" id="nat-grid">${_natTiles(window._natList)}</div></div>`;
  document.body.appendChild(ov);
};
window.natFilter=function(q){ q=(q||'').toLowerCase(); const list=window._natList.filter(n=>n.toLowerCase().includes(q)); const el=document.getElementById('nat-grid'); if(el) el.innerHTML=_natTiles(list); };

